            height: 44px;
            border-radius: 8px;
            background: #24202a;
            Text {
                x: 12px;
                width: parent.width - 24px;
                text: root.event-text;
                color: #b7a8db;
                font-size: 11px;
                vertical-alignment: center;
                overflow: elide;
            }
        }
