component MacAiSetupWindow inherits Window {
    no-frame: true;
    always-on-top: true;
    title: @tr("AI bridge setup");
    default-font-family: Theme.font-sans;
    background: Theme.bg-surface;
    preferred-width: 460px;
    preferred-height: 274px;

    in-out property <string> bridge-url;
    // Typed token. Never populated from the stored config; cleared on Save.
    in-out property <string> token-input;
    // A stored token exists, so leaving the field blank keeps it.
    in property <bool> token-stored: false;
    // Status code (words stay in @tr below): 0 missing · 1 configured ·
    // 2 check the fields · 3 saved · 4 save failed.
    in property <int> status-kind: 0;

    callback save-clicked();
    callback cancel-clicked();
    // The header row is the drag handle (native AppKit drag, one callback).
    callback drag-start-requested();

    forward-focus: url-input;

    FocusScope {
        // Esc = Cancel; everything else reaches the focused LineEdit.
        key-pressed(e) => {
            if (e.text == Key.Escape) {
                root.cancel-clicked();
                return accept;
            }
            return reject;
        }
        VerticalLayout {
            padding: 14px;
            spacing: 10px;

            // Header: icon + drag grip + title on a drag handle, close = Cancel.
            HorizontalLayout {
                spacing: Metrics.space-sm;
                Rectangle {
                    horizontal-stretch: 1;
                    height: 30px;
                    TouchArea {
                        mouse-cursor: grab;
                        pointer-event(ev) => {
                            if (ev.button == PointerEventButton.left
                                && ev.kind == PointerEventKind.down) {
                                root.drag-start-requested();
                            }
                        }
                    }
                    HorizontalLayout {
                        spacing: Metrics.space-sm;
                        Rectangle {
                            width: 18px;
                            height: 30px;
                            Image {
                                source: @image-url("../assets/icons/gear.svg");
                                colorize: Theme.accent;
                                width: 16px;
                                height: 16px;
                                image-fit: contain;
                                y: 7px;
                            }
                        }
                        DragGrip { y: 2px; }
                        Text {
                            text: @tr("AI bridge setup");
                            color: Theme.text-secondary;
                            font-size: Metrics.font-body;
                            font-weight: 600;
                            vertical-alignment: center;
                        }
                    }
                }
                CloseButton {
                    clicked => { root.cancel-clicked(); }
                }
            }

            Text {
                text: @tr("Bridge URL");
                color: Theme.text-secondary;
                font-size: Metrics.font-label;
            }
            url-input := LineEdit {
                placeholder-text: @tr("http://your.bridge.host:PORT/v1");
                text <=> root.bridge-url;
            }

            Text {
                text: @tr("Access token");
                color: Theme.text-secondary;
                font-size: Metrics.font-label;
            }
            LineEdit {
                placeholder-text: root.token-stored
                    ? @tr("Leave empty to keep the saved token")
                    : @tr("Paste the access token");
                text <=> root.token-input;
                input-type: password;
            }

            Text {
                text: root.status-kind == 1 ? @tr("The AI bridge is configured.")
                    : root.status-kind == 2 ? @tr("Check the URLs and access token.")
                    : root.status-kind == 3 ? @tr("Saved.")
                    : root.status-kind == 4 ? @tr("Saving the bridge settings failed.")
                    : @tr("The AI bridge is not configured yet.");
                color: root.status-kind == 2 ? Theme.warning
                    : root.status-kind == 3 ? Theme.success
                    : root.status-kind == 4 ? Theme.danger
                    : Theme.text-muted;
                font-size: Metrics.font-label;
                wrap: word-wrap;
            }

            HorizontalLayout {
                spacing: Metrics.space-sm;
                Rectangle { horizontal-stretch: 1; }
                Button {
                    text: @tr("Cancel");
                    clicked => { root.cancel-clicked(); }
                }
                Button {
                    text: @tr("Save");
                    primary: true;
                    clicked => { root.save-clicked(); }
                }
            }
        }
    }
}

component MarkdownSpike inherits Window {
    title: "Slint markdown adapter spike";
    preferred-width: 720px;
    preferred-height: 600px;
    min-width: 320px;
    min-height: 240px;
    background: #14161e;

    in-out property <[MarkdownBlock]> blocks: [];
    in-out property <string> source-name: "(no source loaded)";

    VerticalLayout {
        padding: 16px;
        spacing: 8px;

        // Header bar with the source filename + block count.
        HorizontalLayout {
            spacing: 12px;
            Text {
                text: "Markdown spike";
                font-size: 16px;
                font-weight: 700;
                color: #e8e8ec;
            }
            Text {
                text: root.source-name + " · " + root.blocks.length + " blocks";
                font-size: 11px;
                color: #999;
                vertical-alignment: center;
            }
        }

        Rectangle {
            background: #2a2c3a;
            height: 1px;
        }

        // Rendered markdown.
        ScrollView {
            vertical-stretch: 1;
            VerticalLayout {
                spacing: 6px;

                for block[i] in root.blocks: Rectangle {
                    background: transparent;
                    horizontal-stretch: 1;

                    // H1
                    if block.kind == 1 : Text {
                        text: block.display-text;
                        font-size: 22px;
                        font-weight: 700;
                        color: #e8e8ec;
                        wrap: word-wrap;
                    }
                    // H2
                    if block.kind == 2 : Text {
                        text: block.display-text;
                        font-size: 17px;
                        font-weight: 700;
                        color: #c8c8cc;
                        wrap: word-wrap;
                    }
                    // H3
                    if block.kind == 3 : Text {
                        text: block.display-text;
                        font-size: 14px;
                        font-weight: 700;
                        color: #a8a8ac;
                        wrap: word-wrap;
                    }
                    // Paragraph
                    if block.kind == 0 : Text {
                        text: block.display-text;
                        font-size: 13px;
                        color: #b8b8bc;
                        wrap: word-wrap;
                    }
                    // BulletItem — render with • prefix
                    if block.kind == 4 : HorizontalLayout {
                        padding-left: 16px;
                        spacing: 8px;
                        Text {
                            text: "•";
                            font-size: 13px;
                            color: #6cf;
                            width: 12px;
                        }
                        Text {
                            text: block.display-text;
                            font-size: 13px;
                            color: #b8b8bc;
                            wrap: word-wrap;
                        }
                    }
                    // CodeBlock — monospace in a darker box
                    if block.kind == 5 : Rectangle {
                        background: #0d0f15;
                        border-radius: 4px;
                        border-width: 1px;
                        border-color: #2a2c3a;
                        VerticalLayout {
                            padding: 10px;
                            spacing: 0px;
                            if block.lang != "" : Text {
                                text: block.lang;
                                font-size: 9px;
                                color: #666;
                            }
                            Text {
                                text: block.display-text;
                                font-size: 12px;
                                color: #d8e8f8;
                                font-family: "Consolas";  // monospace fallback
                                wrap: no-wrap;
                            }
                        }
                    }
                    // HorizontalRule
                    if block.kind == 6 : Rectangle {
                        background: #2a2c3a;
                        height: 1px;
                    }
                }
            }
        }
    }
}

global Metrics {
    // ---- Spacing ----
    // Gaps between siblings + container padding. The 4 / 8 / 12 / 16 scale is
    // overwhelmingly what the UI already uses; xl is reserved (design-doc
    // canonical step) for future breathing room — no current literal harvests
    // to 24px (the largest in use today is the wizard's 20px page padding).
    out property <length> space-xs: 4px;   // dozens of `spacing: 4px` (tile body, bar groups, settings rows)
    out property <length> space-sm: 8px;   // the dominant gap — every surface (`spacing: 8px`, `padding-left: 8px`)
    out property <length> space-md: 12px;  // section gaps + window padding (palette/replay/help row spacing, recover spacing)
    out property <length> space-lg: 16px;  // standard frameless-window padding (help/recover/settings/markdown `padding: 16px`)
    out property <length> space-xl: 24px;  // RESERVED — design-doc canonical; no current literal (largest used = 20px wizard)

    // ---- Radius ----
    // Three rounding steps. Controls (chips, pills) round at 10; window /
    // panel cards round at 12. (Small 4px button + code-block rounding is
    // below the control step and stays a literal where used — out of scope
    // for these two surfaces tonight.)
    out property <length> radius-control: 10px;  // chips/pills — bar Chip/LiveChip/RecordBtn + palette recent chip `border-radius: 10px`
    out property <length> radius-panel: 12px;    // panel/card wrapper — bar + palette + replay chips + settings card `border-radius: 12px`
    out property <length> radius-window: 12px;   // frameless window card outer radius (same step as panel today)
    // Redesign «Glacier» radii — NEW visual values (NOT harvested): consume
    // surface-by-surface with a visual check; these CHANGE the look vs today.
    out property <length> radius-pill: 999px;    // fully-round pills / icon-buttons / status dots (redesign .pill / .ib)
    out property <length> radius-field: 8px;     // form fields + small action buttons (redesign .inp / .ibtn / tile-foot)

    // ---- Control size ----
    // Fixed heights keep "same element = same height" (§4 Геометрия). Bar
    // chips are 22; small inline pills 20; header / button-cluster rows 28.
    out property <length> control-sm: 20px;       // small pill height — tile source pill, palette recent chip, trigger badge `height: 20px`
    out property <length> control-md: 22px;       // bar chip height — Chip/LiveChip/RecordBtn/status pill + replay chip `height: 22px`
    out property <length> control-lg: 28px;       // header / icon-button row height — tile chrome buttons + help header `height: 28px`
    out property <length> icon-button-size: 30px; // square icon-button width — tile copy/regen/escalate/close `width: 30px`
    // Redesign «Glacier» control scale 28 / 36 / 44 (extends the harvested
    // 20/22/28 above; 28 == control-lg). NEW visual values — consume per surface
    // with a check, and NEVER feed one into apply_bar_size / a window preferred-
    // size without the paired Rust change (window sizes are Slint↔Rust-synced).
    out property <length> control-xl: 36px;       // fields, search rows, archive rows, segmented control (redesign .inp/.ibtn h36)
    out property <length> control-xxl: 44px;      // large primary actions (top of the redesign 28/36/44 scale)

    // ---- Typography (SIZES only) ----
    // The font FAMILY stays in Theme.font-sans / Theme.font-mono; these are the
    // recurring point sizes by role. body 12 + label 11 are the two workhorses;
    // caption 10 for meta; heading 18 for the few real titles (§4: «крупный
    // заголовок только там, где он действительно нужен»). 13/14/15px one-offs
    // (H3, sub-headers) have no token and stay literals.
    out property <length> font-caption: 10px;  // meta/secondary — source labels, hints, counts (`font-size: 10px`)
    out property <length> font-label: 11px;    // chip/label text — bar chips, settings rows, hotkey rows (`font-size: 11px`)
    out property <length> font-body: 12px;     // body copy — tile paragraphs, help descriptions, list bodies (`font-size: 12px`)
    out property <length> font-heading: 18px;  // headings — wizard step titles, replay/tile H1 (`font-size: 18px`)

    // ---- Border ----
    out property <length> border-thin: 1px;   // the universal hairline — every `border-width: 1px` + 1px dividers
    out property <length> border-focus: 2px;  // emphasis/focus stroke — capture-overlay selection rect `border-width: 2px`

    // ---- Motion ----
    // Animation durations. fast (120ms) is harvested from the bar's record-chip
    // + settings colour fades; normal (200ms) is GUESSED (design-doc canonical
    // — no 200ms literal exists; the only other duration in use is settings'
    // 140ms nav/slide). Retune when a surface adopts it.
    out property <duration> motion-fast: 120ms;   // `animate ... { duration: 120ms; }` — overlay_bar record chip, settings
    out property <duration> motion-normal: 200ms; // GUESSED — design-doc canonical; closest real literal is 140ms (settings nav)

    // ---- Opacity ----
    // surface (0.92) is the translucent bar/tile fill alpha. muted (0.05) and
    // disabled (0.5) are kept as low-level tokens for future custom muted/
    // disabled states; std-widgets still handle their own disabled tint.
    out property <float> surface-opacity: 0.92;   // bar + tile `Theme.bg-surface.with-alpha(0.92)`
    out property <float> muted-opacity: 0.05;
    out property <float> disabled-opacity: 0.5;   // GUESSED — no current literal; sensible dim for a future disabled control
}

global OverlayCursorPolicy {
    in-out property <bool> force-arrow: false;
}

component IconSlot inherits Rectangle {
