component Chip inherits Rectangle {
    in property <string> label;
    // Design-system icon (skia-safe line SVG, tinted by `colorize` to the
    // chip's semantic colour). When `has-icon` is set, the icon renders in
    // place of (or alongside) the text. Icon-only chips set `a11y` so screen
    // readers still get a word instead of a glyph.
    in property <image> icon;
    in property <bool> has-icon: false;
    in property <string> a11y;
    in property <bool> active: false;
    in property <color> accent: Theme.accent;
    // Render the label in the mono font (Cascadia) — for the session timer so
    // the ticking digits don't shift width frame to frame.
    in property <bool> mono: false;

    callback clicked();

    accessible-role: button;
    accessible-label: a11y != "" ? a11y : label;

    // Hover + press feedback so a click is visibly registered. Action chips
    // (Stop / Expand / X …) had NO feedback at all — only the persistent
    // `active` toggle changed the background — so a click looked like nothing
    // happened (reported for the compact Stop). `active` still wins; otherwise
    // pressed flashes the accent, hover lifts a subtle fill.
    background: active
        ? accent.with-alpha(0.18)
        : (ta.pressed
            ? accent.with-alpha(0.34)
            : (ta.has-hover ? Theme.border-strong.with-alpha(0.22) : transparent));
    border-color: active ? accent : (ta.has-hover ? accent.with-alpha(0.6) : Theme.border-strong);
    border-width: Metrics.border-thin;
    border-radius: Metrics.radius-control;
    height: Metrics.control-md;
    horizontal-stretch: 0;
    animate background { duration: 80ms; }

    HorizontalLayout {
        padding-left: Metrics.space-sm;
        padding-right: Metrics.space-sm;
        spacing: Metrics.space-xs;
        alignment: center;
        if root.has-icon : IconSlot {
            icon: root.icon;
            tint: active ? accent : Theme.text-secondary;
            glyph-size: 14px;
            slot-width: 14px;
            slot-height: 22px;
        }
        if root.label != "" : Text {
            text: label;
            font-family: root.mono ? Theme.font-mono : "";
            font-size: Metrics.font-label;
            color: active ? accent : Theme.text-secondary;
            vertical-alignment: center;
        }
    }
    ta := TouchArea {
        mouse-cursor: OverlayCursorPolicy.force-arrow ? default : pointer;
        clicked => { root.clicked(); }
    }
}

component LockModeMenuRow inherits Rectangle {
    in property <string> label;
    in property <bool> current: false;
    // The selector is a compact traffic light: neutral unlocked, amber
    // listening, red unloaded.  The colour stays on the row icon even before
    // selection so the consequence of each choice is apparent.
    in property <color> mode-color: Theme.text-secondary;
    in property <bool> unlocked: false;
    callback clicked();

    accessible-action-default => { root.clicked(); }

    height: 30px;
    border-radius: Metrics.radius-control;
    background: root.current ? root.mode-color.with-alpha(0.14) : (row-touch.has-hover ? Theme.bg-surface : transparent);
    border-width: root.current ? Metrics.border-thin : 0px;
    border-color: root.current ? root.mode-color.with-alpha(0.65) : transparent;
    accessible-role: button;
    accessible-label: root.label;
    accessible-checkable: true;
    accessible-checked: root.current;
    HorizontalLayout {
        padding-left: Metrics.space-sm;
        padding-right: Metrics.space-sm;
        spacing: Metrics.space-sm;
        Image {
            source: root.unlocked ? @image-url("../assets/icons/unlock.svg") : @image-url("../assets/icons/lock.svg");
            colorize: root.mode-color;
            width: 14px;
            height: 14px;
            y: (parent.height - self.height) / 2;
        }
        Text {
            text: root.label;
            color: root.current ? root.mode-color : Theme.text-secondary;
            font-size: Metrics.font-label;
            vertical-alignment: center;
        }
        Rectangle { horizontal-stretch: 1; }
        if root.current : Text {
            text: @tr("Current");
            color: root.mode-color;
            font-size: Metrics.font-label;
            vertical-alignment: center;
        }
    }
    row-touch := TouchArea {
        mouse-cursor: OverlayCursorPolicy.force-arrow ? default : pointer;
        clicked => { root.clicked(); }
    }
}

component LockChip inherits Rectangle {
    in property <bool> locked: false;
    in property <bool> unlocked: !root.locked;
    // Deep lock (managed-local third state, v0.37): implies `locked`, turns
    // the chip red and STOPS the tremble — an unloaded server is a firm,
    // static state, distinct from the shaking "tiles held back" listening mode.
    in property <bool> deep: false;
    in property <string> a11y;
    in property <bool> managed: false;
    // The full 1280px bar has no spare width once live tiles add their
    // controls. Keep the state explicit, but use the short label in that
    // deterministic tight layout instead of letting Slint clip this text
    // under the following action chips.
    in property <bool> tight: false;
    // 0 = normal, 1 = listening, 2 = deep. Rust owns the durable transition.
    in property <int> mode: 0;
    in property <color> accent: root.deep ? Theme.danger : #f59e0b;
    callback mode-selected(int);
    callback menu-opened(length, length);
    property <bool> phase: false;

    accessible-role: button;
    accessible-label: a11y;
    accessible-checkable: true;
    accessible-checked: locked;
    accessible-action-default => { root.menu-opened(root.absolute-position.x + root.width, root.absolute-position.y + root.height); }
    background: locked
        ? accent.with-alpha(0.18)
        : (ta.pressed
            ? accent.with-alpha(0.34)
            : (ta.has-hover ? Theme.border-strong.with-alpha(0.22) : transparent));
    border-color: locked ? accent : (ta.has-hover ? accent.with-alpha(0.6) : Theme.border-strong);
    border-width: Metrics.border-thin;
    border-radius: Metrics.radius-control;
    height: Metrics.control-md;
    min-width: 30px;
    horizontal-stretch: 0;
    animate background { duration: 80ms; }

    // Trembles only while locked in LISTENING mode: flip `phase` every 90ms and
    // let `animate` swing the padlock between +7° and -7°, so it visibly shakes;
    // at rest (unlocked) it sits flat, and a DEEP lock holds it still.
    Timer {
        interval: 90ms;
        running: root.locked && !root.deep;
        triggered => {
            root.phase = !root.phase;
        }
    }
    HorizontalLayout {
        padding-left: Metrics.space-sm;
        padding-right: Metrics.space-sm;
        spacing: Metrics.space-xs;
        alignment: center;

        Image {
            source: root.unlocked ? @image-url("../assets/icons/unlock.svg") : @image-url("../assets/icons/lock.svg");
            colorize: root.locked ? root.accent : Theme.text-secondary;
            width: 14px;
            height: 14px;
            y: (parent.height - self.height) / 2;
            // transform-rotation pivots around the element centre by default → a clean wobble.
            transform-rotation: root.locked && !root.deep ? (root.phase ? 7deg : -7deg) : 0deg;
            animate transform-rotation {
                duration: 85ms;
                easing: ease-in-out;
            }
        }
        if root.deep : Text {
            text: root.tight ? @tr("AI off") : @tr("Local AI unloaded");
            font-size: Metrics.font-label;
            color: root.accent;
            vertical-alignment: center;
        }
    }
    ta := TouchArea {
        mouse-cursor: OverlayCursorPolicy.force-arrow ? default : pointer;
        // The old popup was clipped to the bar's 64px native client area. Rust
        // opens the separate LockModeMenuWindow at this chip's screen anchor.
        clicked => { root.menu-opened(root.absolute-position.x + root.width, root.absolute-position.y + root.height); }
    }
}

component LiveChip inherits Rectangle {
    in property <string> label;
    in property <image> icon;
    in property <bool> has-icon: false;
    in property <string> a11y;
    in property <bool> active: false;
    in property <color> accent: Theme.success;

