            slot-height: 22px;
        }
        if root.label != "" : Text {
            text: label;
            font-size: Metrics.font-label;
            color: active ? accent : Theme.text-secondary;
            vertical-alignment: center;
        }
    }
    TouchArea { clicked => { root.clicked(); } }
}

component RecordBtn inherits Rectangle {
    in property <string> label;
    // Source icon (mic / speaker), tinted like the label.
    in property <image> icon;
    in property <bool> has-icon: false;
    in property <color> accent: Theme.success;
    in property <bool> recording: false;
    callback pressed();
    callback released();

    // V0.8.4 — Telegram-style swipe-up-to-lock. Default flow is unchanged:
    // hold to record (pressed), release to send (released). NEW: while holding,
    // drag up past `lock-dy` → hands-free "locked" recording — releasing the
    // button no longer stops it (the chip becomes a STOP button: the dot turns
    // into a square; a fresh click stops + sends, reusing `released()`). Recording
    // is "record-until-released" in Rust, so locking just defers the released()
    // call — no Rust change needed. `press-y` is the pointer y at press; the
    // TouchArea grabs the pointer on press so `moved` keeps firing past the bounds.
    in-out property <bool> locked: false;
    property <length> press-y;
    property <bool> swallow-up: false;
    // Threshold kept small: the bar is pinned at the TOP of the screen, so the
    // cursor clamps at the screen edge ~43px above the chip — a larger threshold
    // would be unreachable without first moving the bar down.
    property <length> lock-dy: 24px;

    accessible-role: button;
    accessible-label: label;

    background: recording ? Theme.danger.with-alpha(0.2) : transparent;
    border-color: recording ? Theme.danger : Theme.border-strong;
    border-width: Metrics.border-thin;
    border-radius: Metrics.radius-control;
    height: Metrics.control-md;
    horizontal-stretch: 0;
    animate background, border-color { duration: 120ms; }

    // Reset the lock whenever recording ends from any cause (release, stop-click,
    // watchdog timeout) so the chip never gets stuck in the locked/stop look.
    changed recording => {
        if (!self.recording) {
            self.locked = false;
        }
    }

    HorizontalLayout {
        padding-left: Metrics.space-sm;
        padding-right: Metrics.space-sm;
        spacing: Metrics.space-xs;
        // Record dot: filled red while recording; a SQUARE (border-radius 0)
        // once locked to read as a "stop" affordance; hollow accent ring idle.
        Rectangle {
            width: 8px;
            height: 8px;
            border-radius: root.locked ? 0px : 4px;
            y: (parent.height - self.height) / 2;
            background: root.recording ? Theme.danger : transparent;
            border-width: root.recording ? 0px : 1px;
            border-color: root.accent;
        }
        if root.has-icon : IconSlot {
            icon: root.icon;
            tint: root.recording ? Theme.danger : Theme.text-secondary;
            glyph-size: 14px;
            slot-width: 14px;
            slot-height: 22px;
        }
        Text {
            text: root.label;
            font-size: Metrics.font-label;
            color: root.recording ? Theme.danger : Theme.text-secondary;
            vertical-alignment: center;
        }
        if root.recording : IconSlot {
            icon: root.locked
                ? @image-url("../assets/icons/stop.svg")
                : @image-url("../assets/icons/arrow-up.svg");
            tint: root.locked ? Theme.danger : Theme.warning;
            glyph-size: 12px;
            slot-width: 12px;
            slot-height: 22px;
        }
    }
    TouchArea {
        mouse-cursor: OverlayCursorPolicy.force-arrow ? default : pointer;
        pointer-event(ev) => {
            if (ev.button == PointerEventButton.left) {
                if (ev.kind == PointerEventKind.down) {
                    if (root.locked) {
                        // Fresh click while locked = STOP (same as a release).
                        root.locked = false;
                        root.swallow-up = true;
                        root.released();
                    } else {
                        root.press-y = self.mouse-y;
                        root.swallow-up = false;
                        root.pressed();
                    }
                }
                if (ev.kind == PointerEventKind.up) {
                    if (root.swallow-up) {
                        root.swallow-up = false;
                    } else if (!root.locked) {
                        root.released();
                    }
                    // locked && !swallow-up = the release that follows a lock →
                    // keep recording hands-free (do nothing).
                }
            }
        }
        moved => {
            // Gate on `recording` so a chip whose recording never started (e.g.
            // the mic was busy → on_ptt_*_pressed bailed) can't show a locked /
            // stop look without actually recording.
            if (self.pressed && root.recording && !root.locked
                && root.press-y - self.mouse-y > root.lock-dy) {
                root.locked = true;
            }
        }
    }
}

component VDivider inherits Rectangle {
    width: 1px;
    height: 16px;
    background: Theme.border-strong;
}

component OverlayBarWindow inherits Window {
    // Phase 4 — keep std-widgets (Button etc.) dark with the active scheme
    // instead of Slint's light fluent default. See settings_panel for detail.
    property <bool> widgets-light: Theme.is-light;
    init => { Palette.color-scheme = root.widgets-light ? ColorScheme.light : ColorScheme.dark; }
    changed widgets-light => { Palette.color-scheme = root.widgets-light ? ColorScheme.light : ColorScheme.dark; }
    title: @tr("suflyor (Slint)");
    icon: @image-url("../assets/icon.svg");
    background: transparent;
    no-frame: true;
    always-on-top: true;
    // Phase E6 v10 — widened from 720 to 980 so new chip labels
    // (💡 tips, ⭐ bm, 🎯 stealth, 🔥 auto, ⚙ settings, X quit) all
    // fit without truncating the rightmost (X quit) chip.
    // Phase E6 v11 — height bumped 56 → 86 to fit live transcript row.
    // Phase E6 v38 — widened 980 → 1140: the Russian chip labels
    // (подсказки / закладка / скрытность / настройки / выход) are wider
    // than the English originals and were clipping the rightmost chip.
    // Phase E6 v44 — narrowed 1320 → 1000: the grouped layout makes the
    // capture toggles + quick actions icon-only, so the row is far more
    // compact (icons + 3 short labels instead of 15 text chips).
    // E10.2 — 1000 → 1080 after the "close all" chip landed, so the Settings
    // + quit chips never clip; the active-stack readout moved to the bottom
    // status row to keep the action row compact.
    // V0.8.3 — 1080 → 1120 to absorb the new ✏ "Написать" chip's width and keep
    // the un-armed RU worst case (wide "⚠ AI недоступен" status + close-all + 2
    // open tiles) comfortably inside the fixed-width bar (single-row layout, so
    // total content — not cluster placement — is what clips).
    // Phase 3a — 1120 → 1160 to absorb the new 🗄 archive chip with the SAME
    // worst-case slack as the verified 1120 baseline (icon-only chip ≈ 30 px).
    // v0.12.0 — 1160 → 1200 to absorb the new 📝 Summary chip (icon-only,
    // ≈ 30 px) with the same RU worst-case slack (review-agent finding).
    // v0.36.1-rc.2 — 1200 → 1280 so the permanent RU deep-lock label still
    // leaves room for Pause + Close all in the running/open-tile worst case.
    preferred-width: root.bootstrap-mode ? 560px : 1280px;
    // 64px (was 86) — the chip row is only 22px, so 86 left a wide empty band
    // around one status line (design review #1). Kept in sync with apply_bar_size
    // in overlay_host.rs.
    preferred-height: 64px;
    // Relax the min-width in compact "narrow session" mode so the runtime
    // set_size(680) isn't clamped back up (Slint propagates min-width to the OS
    // as a minimum inner size). Compact still needs room for status + спросить +
    // захватить + timer + the persistent deep-lock label + expand in one row,
    // so 660 (not the old 300 reader pill). Full bar keeps 720 so its chip row
    // never collapses. Kept in sync with apply_bar_size in overlay_host.rs.
    min-width: root.bootstrap-mode ? 440px : (root.compact-bar ? 660px : 720px);

    // Status pill text (idle / recording / etc).
    in-out property <string> status-text: "idle";
    in-out property <color> status-color: Theme.text-muted;

    // Live capture flags.
    in-out property <bool> mic-active: false;
    // v0.13.1 — mic muted (drops mic transcript + mic recording). Drives the
    // mic chip's slashed-icon + dimmed look.
    in-out property <bool> mic-muted: false;
    in-out property <bool> sys-active: false;

    // Session timer label (formatted by Rust, e.g. "03:42").
    in-out property <string> timer-label: "00:00";
    in-out property <bool> timer-active: false;
    // v0.22.0 — true while the running session is PAUSED. Drives the Pause
    // chip's play/pause icon + the frozen timer; set by Rust.
    in-out property <bool> session-paused: false;
    // v0.22.0 — the active session's short title (auto-named, later editable).
    // Shown next to the timer while a session runs; empty until the namer fills
    // it. Set by Rust (the bar tick mirrors SlintRuntime.session_name).
    in-out property <string> session-name: "";

    // Phase E10.2 — read-only "active stack" readout: which STT engine +
    // which AI model are actually live, with a 🟢 local / ☁ cloud / ◐ mixed
    // icon. So the user can tell at a glance what's transcribing + answering.
    in-out property <string> active-stack: "";
    // Current request phases (load/TTFT/total/decode/effective), polled from the
    // backend and appended to the active-stack footer. Empty after 30s so an old
    // fast request is never presented as the speed of current work.
    in-out property <string> tok-per-sec: "";
    // macOS process-footprint samples, formatted by Rust. The MLX value is the
    // sidecar's unified-memory process footprint, not discrete VRAM.
    in-out property <string> app-memory: "";
    in-out property <string> mlx-memory: "";

    // Tile counter for the "+ Tile" button.
    in-out property <int> tiles-spawned: 0;

    // #B1 — LIVE count of currently-open tiles (Rust keeps this in sync with
    // the TileWindows vec on every spawn/close). Drives the "+ tile (N)" label
    // and gates the "close all" chip, so closing tiles via their own X buttons
    // updates the bar (tiles-spawned is a CUMULATIVE counter and must NOT be
    // used for these — it never decrements except on close-all).
    in-out property <int> open-tiles: 0;
    // One bounded recovery slot for a read-aloud tile closed by mistake.
    in-out property <bool> can-restore-tile: false;

    // Phase E6 v10 — aggressive (every-line) auto-tile mode flag.
    // When true, the bar shows the "🔥 auto" chip lit; user can
    // toggle to spawn a tile on every transcript line (vs. only on
    // Question/Keyword triggers). Backend already supports it via
    // cfg.auto_tile_every_line; this just surfaces the switch.
    in-out property <bool> aggressive-active: false;
    // E10.2 — stealth on/off, so the 🎯 chip lights up + reflects restored state.
    in-out property <bool> stealth-active: false;
    changed stealth-active => {
        OverlayCursorPolicy.force-arrow = root.stealth-active;
    }
    // I1/I4 — verified stealth FAILURE: a WDA apply/readback (or the F8 capture
    // overlay's HWND grab) failed, so the status pill shows the translated
    // generic failure text instead of the mic/sys status until the next apply
    // verifies. Set/cleared by Rust (surface_stealth_unavailable clears in
    // apply_bar_stealth); the pill TEXT is translated here so RU follows
    // ui_language (the pill's colour stays Rust-owned — colours don't translate).
    in-out property <bool> stealth-fault: false;
    property <string> presented-status: root.stealth-fault
        ? @tr("[!] stealth unavailable")
        : root.status-text;

    // Phase E6 v11 — live status indicators. `last-transcript-line`
    // shows the most recent STT output (truncated by Rust to ~120
    // chars) below the chip row so user sees "транскрипция работает".
    // `ai-streaming` lights up the AI model chip background pulse so
    // user sees "AI работает" while a tile is mid-stream.
    in-out property <string> last-transcript-line: "";
    in-out property <bool> ai-streaming: false;
    // Source tag for the transcript line — "mic" / "sys" / "" to
    // colour-code which side of the conversation it came from.
    in-out property <string> last-transcript-source: "";

    // Phase E6 v42 — push-to-record (hold) state. Rust flips these true
    // while the corresponding source is recording so the button glows red.
    in-out property <bool> mic-recording: false;
    in-out property <bool> sys-recording: false;

    // Phase E6 v45 — ⚙ Settings chip lights up while the Settings window
    // is open (Rust flips this on open / close). User: "значок настроек
    // не загорается когда настройки открыты".
    in-out property <bool> settings-open: false;
    in-out property <bool> help-open: false;
    // Phase 3a — lights the 🗄 archive chip while the archive window is open
    // (same as settings-open / help-open).
    in-out property <bool> archive-open: false;
    // Phase E6 v45 — X quit is two-step: first press arms an inline
    // "Quit? Yes/No" confirm (Rust auto-disarms after a few seconds) so a
    // stray click can't kill the app. User: "крестик моментально всё
    // закрывает без предупреждения".
    in-out property <bool> quit-armed: false;
    // V0.8.0 (Поток B) — emergency-restart inline confirm, same two-step UX.
    in-out property <bool> restart-armed: false;
    // v0.8.2 (M1 fix) — true while EITHER inline confirm (quit / restart) is
    // showing. The confirm expands the action row inline, so we hide the
    // secondary right-cluster chips (close-all / + tile / 📷 / ⚙) while it's
    // up, keeping the row inside the fixed 1080px bar. Before this, RU
    // "Перезапустить? Да Нет" + the "close all" chip + the wide "⚠ AI
    // недоступен" status pushed "Нет" (cancel) off the right edge — exactly in
    // the restart-while-AI-down flow the feature exists for. The un-armed bar
    // is pixel-identical to before (chips only hide during the ≤4s confirm).
    property <bool> confirming: root.quit-armed || root.restart-armed;
    // A live tile makes the fixed-width action row tight. Keep the established
    // text actions stable and shorten only the deep-lock state label.
    property <bool> tight-open-tiles: root.open-tiles > 0;

    // v0.12.0 — true while a Summary request is in flight. Lights the 📝
    // chip AND doubles as the Rust-side re-click guard (a slow model must
    // not stack parallel summary calls).
    in-out property <bool> summary-busy: false;

    // ===== Compact "reader mode" =====
    // Collapse the wide bar to a narrow session strip (status pill + спросить /
    // захватить + timer + Expand). Persisted via config.compact_bar; Rust resizes
    // the bar window on toggle.
    in-out property <bool> compact-bar: false;
    // macOS production bootstrap: keep the real product bar/window while its
    // platform adapters are connected, but never expose dead AI/audio controls.
    in property <bool> bootstrap-mode: false;
    // macOS bootstrap only: raw AVFoundation authorization status
    // (0 not determined, 1 restricted, 2 denied, 3 authorized, 4 requesting).
    in-out property <int> mic-permission-state: 0;
    // macOS bootstrap only: 0 stopped, 1 receiving native audio, 2 start failed.
    in-out property <int> mic-capture-state: 0;
    // The hide action is exposed only after Windows accepted the tray icon;
    // otherwise hiding the bar would remove the only restore surface.
    in property <bool> tray-available: false;
    // v0.28 — "listening mode" (config.suppress_tiles): the bar lock chip toggles this; when
    // true, auto AI tiles are suppressed (slint_session::maybe_spawn_auto_tile early-returns).
    in-out property <bool> suppress-tiles: false;
    // v0.37 — deep lock (managed-local only): the lock chip's third state —
    // the app-owned llama-server is unloaded and managed requests are refused.
    // Implies suppress-tiles (Rust keeps the two consistent).
    in-out property <bool> deep-lock: false;
    // Runtime-testable state that directly drives the lock chip's rendered icon.
    out property <bool> lock-icon-unlocked: !root.suppress-tiles && !root.deep-lock;
    // Localized per-state lock-chip description (a11y label; there is no
    // hover-tooltip surface). Rust rebuilds it on transitions + language switch.
    in property <string> lock-a11y: "";
    in property <bool> lock-menu-managed: false;

    // ===== Callbacks =====
    callback mic-toggle-clicked();
    callback lock-menu-opened(length, length);
    callback sys-toggle-clicked();
    // Phase E6 v42 — push-to-record hold callbacks (down = start, up = stop).
    callback ptt-mic-pressed();
    callback ptt-mic-released();
    callback ptt-sys-pressed();
    callback ptt-sys-released();
    callback timer-toggle-clicked();
    // v0.22.0 — Pause/Resume the running session (keeps the SAME session).
    callback pause-toggle-clicked();
    callback spawn-tile-clicked();
    // V0.8.3 — "Написать": open the typed-question input window.
    callback text-ask-clicked();
    callback close-all-tiles-clicked();
    callback restore-tile-clicked();
    callback capture-clicked(); // 📷 screenshot -> vision (same as F8)
    callback stealth-toggle-clicked();
    callback aggressive-toggle-clicked();
    callback lock-mode-selected(int); // 0=normal, 1=listening, 2=unload local AI
    callback open-settings-clicked();
    callback help-clicked();   // 🆘 chip / F1 → open the help window
    callback archive-clicked(); // 🗄 chip / F7 → open the session archive
    callback summary-clicked(); // v0.12.0 — 📝 chip → meeting-summary tile
    callback quit-clicked();   // X pressed → Rust arms the inline confirm
    // V0.8.0 (Поток B) — emergency restart (⟳). Two-step like Quit.
    callback restart-clicked();
    callback restart-confirm();
    callback restart-cancel();
    callback quit-confirm();   // "Yes" → really quit the app
    callback quit-cancel();    // "No" → disarm the confirm
    // Phase E6 v22 — manual cursor-delta drag (replaces modal
    // WM_NCLBUTTONDOWN which left TouchArea stuck pressed). down →
    // drag-start-requested (anchor), move-while-pressed → drag-moved.
    callback drag-start-requested();
    callback drag-moved();
    // Compact mode: collapse/expand the bar.
    callback compact-toggle-clicked();
    // RC4 — hide the bar to the system tray (explicit only; startup is always
    // visible). Recording/hotkeys/TTS keep running; the tray restores the bar.
    callback hide-to-tray-clicked();

    Rectangle {
        background: Theme.bg-surface.with-alpha(0.92);
        border-radius: 12px;
        border-width: 1px;
        border-color: Theme.border;

        // Phase E6 v21 — bar drag is now SCOPED to the status pill
        // only (see drag-handle TouchArea inside the pill below).
        // Cycle 20's full-background TouchArea stole every chip click
        // because Slint's pointer-event fires for ALL events in the
        // bbox even when children have their own TouchAreas (same
        // root cause as tile chrome cycle 10). User: "интерфейс
        // сразу стал не кликабельным". Now only the ~80px status
        // pill is the drag zone; every chip is freely clickable.

        if !root.compact-bar && !root.bootstrap-mode : VerticalLayout {
            padding: 6px;
            spacing: 4px;

        HorizontalLayout {
            padding: 2px;
            spacing: 6px;
            alignment: start;

            // Status pill (left edge) — DOUBLES AS DRAG HANDLE.
            // It has no click action of its own, so a pointer-event
            // TouchArea here is safe: its bbox is only the pill, so
            // it can't shadow the sibling chips' TouchAreas.
            Rectangle {
                background: (root.stealth-fault ? Theme.warning : root.status-color).with-alpha(0.18);
                border-color: root.stealth-fault ? Theme.warning : root.status-color;
                border-width: 1px;
                border-radius: Metrics.radius-control;
                height: 22px;
                horizontal-stretch: 0;
                // The pill is the bar's status readout AND its drag handle —
                // expose both to accessibility (no visible caption describes it).
                accessible-role: text;
                accessible-label: root.presented-status + ". " + @tr("Drag to move the bar; shows the live state");
                // Drag handle — press-and-drag to move the whole bar.
                TouchArea {
                    mouse-cursor: OverlayCursorPolicy.force-arrow ? default : grab;
                    pointer-event(ev) => {
                        if (ev.button == PointerEventButton.left
                            && ev.kind == PointerEventKind.down) {
                            root.drag-start-requested();
                        }
                    }
                    moved => {
                        if (self.pressed) { root.drag-moved(); }
                    }
                }
                HorizontalLayout {
                    padding-left: 4px;
                    padding-right: 8px;
                    spacing: 4px;
                    BrandStateMark {
                        assistant-active: root.ai-streaming;
                        mark-size: 22px;
                    }
                    // Grip — drag affordance (accent). Design-system 6-dot
                    // grip icon (skia-safe) in place of the "::" text.
                    IconSlot {
                        icon: @image-url("../assets/icons/grip.svg");
                        tint: Theme.accent;
                        glyph-size: 12px;
                        slot-width: 12px;
                        slot-height: 22px;
                    }
                    Text {
                        // I1/I4 — a verified stealth failure overrides the
                        // mic/sys status with the translated generic banner.
                        text: root.presented-status;
                        font-size: 11px;
                        font-weight: 600;
                        color: root.stealth-fault ? Theme.warning : root.status-color;
                        vertical-alignment: center;
                    }
                }
            }

            // Phase E6 v44 — grouped, scannable layout (user: "слишком
            // много надписей в ряд"). Groups separated by VDividers:
            // [state] · [capture toggles] · [push-to-ask] · [session info]
            // · [quick actions] · →spring→ · [primary + system]. Toggles
            // and secondary actions are ICON-ONLY; the push-to-record
            // buttons keep words (the key feature) with a colour-coded
            // record dot (green=mic, cyan=sys).

            // ── Capture toggles (continuous mic / sys) — icon-only + dot ──
            LiveChip {
                // v0.13.1 — slashed mic when muted; lit green when live.
                icon: root.mic-muted
                    ? @image-url("../assets/icons/micslash.svg")
                    : @image-url("../assets/icons/mic.svg");
                has-icon: true;
                a11y: root.mic-muted ? "Mic muted (click to unmute)" : "Mic live (click to mute)";
                active: !root.mic-muted;
                accent: root.mic-muted ? Theme.text-muted : Theme.success;
                clicked => { root.mic-toggle-clicked(); }
            }
            LiveChip {
                icon: @image-url("../assets/icons/system-audio.svg");
                has-icon: true;
                a11y: "System audio capture";
                active: root.sys-active;
                accent: Theme.accent;
                clicked => { root.sys-toggle-clicked(); }
            }

            VDivider { }

            // ── Push-to-record (hold to ask) — labelled; dot colour marks
            //    the source: green = mic (your voice), cyan = sys (them).
            RecordBtn {
                icon: @image-url("../assets/icons/mic.svg");
                has-icon: true;
                label: @tr("ask");
                accent: Theme.success;
                recording: root.mic-recording;
                pressed => { root.ptt-mic-pressed(); }
                released => { root.ptt-mic-released(); }
            }
            RecordBtn {
                icon: @image-url("../assets/icons/system-audio.svg");
                has-icon: true;
                label: @tr("grab");
                accent: Theme.accent;
                recording: root.sys-recording;
                pressed => { root.ptt-sys-pressed(); }
                released => { root.ptt-sys-released(); }
            }

            VDivider { }

            // ── Session info (timer) ──
            Chip {
                icon: root.timer-active
                    ? @image-url("../assets/icons/stop.svg")
                    : @image-url("../assets/icons/session-start.svg");
                has-icon: true;
                label: root.timer-active ? root.timer-label : @tr("start");
                active: root.timer-active;
                accent: #fbbf24;
                mono: true;
                clicked => { root.timer-toggle-clicked(); }
            }

            // ── Pause / Resume (v0.22.0) — visible only while a session runs.
            // Pauses recording + transcript + auto-tiles but keeps the SAME
            // session alive; Resume continues it. Manual F9 still works.
            if root.timer-active : Chip {
                icon: root.session-paused
                    ? @image-url("../assets/icons/play.svg")
                    : @image-url("../assets/icons/pause.svg");
                has-icon: true;
                a11y: root.session-paused ? "Resume the session" : "Pause the session";
                active: root.session-paused;
                accent: #fbbf24;
                clicked => { root.pause-toggle-clicked(); }
            }

            VDivider { }

            // ── Quick actions — icon-only (stealth / auto)
            Chip {
                icon: @image-url("../assets/icons/stealth.svg");
                has-icon: true;
                a11y: "Stealth (hide from capture)";
                active: root.stealth-active;
                accent: #ec4899;
                clicked => { root.stealth-toggle-clicked(); }
            }
            Chip {
                icon: @image-url("../assets/icons/flame.svg");
                has-icon: true;
                a11y: "Aggressive auto-tile";
                active: root.aggressive-active;
                accent: #fb923c;
                clicked => { root.aggressive-toggle-clicked(); }
            }
            // 🔒 Lock tiles (listening mode) — stop auto AI tiles popping (e.g. over a game).
            // Trembles while active so their absence is obviously ON PURPOSE. For the
            // app-managed local server the SAME chip runs a third state (deep lock,
            // v0.37): red + still, the managed server unloaded until the next click.
            LockChip {
                locked: root.suppress-tiles;
                unlocked: root.lock-icon-unlocked;
                deep: root.deep-lock;
                a11y: root.lock-a11y;
                managed: root.lock-menu-managed;
                tight: root.tight-open-tiles;
                mode: root.deep-lock ? 2 : (root.suppress-tiles ? 1 : 0);
                mode-selected(mode) => { root.lock-mode-selected(mode); }
                menu-opened(x, y) => { root.lock-menu-opened(x, y); }
            }
            // 🗄 Session archive (also F7) — browse + search past sessions.
            // Icon-only + left of the spring so it consumes slack, not the
            // width-sensitive right cluster. Lights while the archive is open.
            Chip {
                icon: @image-url("../assets/icons/archive.svg");
                has-icon: true;
                a11y: "Session archive";
                active: root.archive-open;
                accent: #a78bfa;
                clicked => { root.archive-clicked(); }
            }
            // v0.12.0 — Summary созвона: run the full-session transcript
            // through the AI → structured recap tile (participants / topics /
            // decisions / tasks / agreements). Works mid-session AND after
            // Стоп. Lights while the request is in flight.
            Chip {
                icon: @image-url("../assets/icons/summary.svg");
                has-icon: true;
                a11y: "Meeting summary";
                active: root.summary-busy;
                accent: #38bdf8;
                clicked => { root.summary-clicked(); }
            }

            // Spring spacer — pushes the primary + system cluster right.
            Rectangle { horizontal-stretch: 1; min-width: 12px; }

            // ── Primary + system ──
            // Close-all appears once tiles have been spawned so the user can
            // dismiss a screenful in one click (#110); resets the counter,
            // which also hides this chip again.
            if root.open-tiles > 0 && !root.confirming : Chip {
                label: @tr("close all");
                a11y: @tr("close all");
                accent: #fb7185;
                clicked => { root.close-all-tiles-clicked(); }
            }
            if root.can-restore-tile && !root.confirming : Chip {
                icon: @image-url("../assets/icons/restore.svg");
                has-icon: true;
                a11y: @tr("Restore last tile");
                accent: #34d399;
                clicked => { root.restore-tile-clicked(); }
            }
            // V0.8.3 — ✏ Написать: type a question when speaking aloud isn't an
            // option. Opens a small stealth-aware input window.
            if !root.confirming : Chip {
                icon: @image-url("../assets/icons/pencil.svg");
                has-icon: true;
                a11y: "Write a question";
                accent: #34d399;
                clicked => { root.text-ask-clicked(); }
            }
            if !root.confirming : Chip {
                label: @tr("+ tile ({})", root.open-tiles);
                a11y: @tr("+ tile ({})", root.open-tiles);
                accent: #f472b6;
                clicked => { root.spawn-tile-clicked(); }
            }
            if !root.confirming : Chip {
                icon: @image-url("../assets/icons/camera.svg");
                has-icon: true;
                a11y: "Screenshot to vision";
                accent: #22d3ee;
                clicked => { root.capture-clicked(); }
            }
            if !root.confirming : Chip {
                icon: @image-url("../assets/icons/gear.svg");
                has-icon: true;
                a11y: "Settings";
                active: root.settings-open;
                accent: Theme.text-muted;
                clicked => { root.open-settings-clicked(); }
            }
            // V0.8.4 — 🆘 help (icons + hotkeys + gestures); also F1. Lights up
            // while the help window is open (same as the ⚙ chip for Settings).
            if !root.confirming : Chip {
                icon: @image-url("../assets/icons/sos.svg");
                has-icon: true;
                a11y: "Help";
                active: root.help-open;
                accent: #60a5fa;
                clicked => { root.help-clicked(); }
            }
            // V0.8.0 (Поток B) — emergency restart, two-step like Quit. Use it
            // when the app/local AI gets stuck; settings (incl. stealth) survive.
            // Label is the recycle EMOJI 🔄 (color-emoji font), NOT the text
            // glyph ⟳ (U+27F3) — the latter renders as a missing-glyph box on
            // the Slint+skia text-font fallback (same class as ✕, why Quit uses
            // ASCII "X"). 🔄 renders fine (proven by tile.slint's regen button).
            if !root.restart-armed : Chip {
                icon: @image-url("../assets/icons/restart.svg");
                has-icon: true;
                a11y: "Emergency restart";
                accent: #38bdf8;
                clicked => { root.restart-clicked(); }
            }
            if root.restart-armed : HorizontalLayout {
                spacing: 4px;
                Text {
                    text: @tr("Restart?");
                    font-size: 11px;
                    font-weight: 600;
                    color: Theme.text-primary;
                    vertical-alignment: center;
                }
                Chip {
                    label: @tr("Yes");
                    active: true;
                    accent: #38bdf8;
                    clicked => { root.restart-confirm(); }
                }
                Chip {
                    label: @tr("No");
                    accent: Theme.accent;
                    clicked => { root.restart-cancel(); }
                }
            }
            // Compact "reader mode" — collapse the bar to a small read-aloud
            // pill. Lives with the window controls (left of Quit), where a
            // minimize/collapse affordance is expected. Hidden during a quit/
            // restart confirm so the inline buttons stay inside the bar.
            if !root.confirming : Chip {
                icon: @image-url("../assets/icons/minimize.svg");
                has-icon: true;
                a11y: "Compact reader mode";
                active: root.compact-bar;
                accent: #38bdf8;
                clicked => { root.compact-toggle-clicked(); }
            }
            // RC4 — hide the bar to the system tray, immediately beside the
            // compact control. Explicit only — startup is always visible; the
            // tray icon restores the bar (same compact mode). Recording,
            // hotkeys, TTS and session tasks keep running while hidden.
            if root.tray-available && !root.confirming : Chip {
                icon: @image-url("../assets/icons/tray.svg");
                has-icon: true;
                a11y: @tr("Hide to tray");
                accent: #38bdf8;
                clicked => { root.hide-to-tray-clicked(); }
            }
            // Quit — two-step. Idle: a single ASCII "X" (Unicode ✕ renders
            // as a missing-glyph box on the Slint+skia fallback). Armed:
            // inline "Quit? [Yes] [No]" so a stray click can't kill the app.
            if !root.quit-armed : Chip {
                icon: @image-url("../assets/icons/x.svg");
                has-icon: true;
                a11y: "Quit";
                accent: Theme.danger;
                clicked => { root.quit-clicked(); }
            }
            if root.quit-armed : HorizontalLayout {
                spacing: 4px;
                Text {
                    text: @tr("Quit?");
                    font-size: 11px;
                    font-weight: 600;
                    color: Theme.text-primary;
                    vertical-alignment: center;
                }
                Chip {
                    label: @tr("Yes");
                    active: true;
                    accent: Theme.danger;
                    clicked => { root.quit-confirm(); }
                }
                Chip {
                    label: @tr("No");
                    accent: Theme.accent;
                    clicked => { root.quit-cancel(); }
                }
            }
        }

        // ===== Live status row =====
        // Phase E6 v11 — bottom row shows last transcript line + AI
        // streaming indicator. Gives the user immediate visual proof
        // that STT and AI are working without opening a separate
        // window or watching a log file.
        HorizontalLayout {
            padding-left: 4px;
            padding-right: 4px;
            spacing: 6px;
            // Session name (v0.22.0) — relocated here from the top chip row so it
            // no longer pushes the action chips; a small 10px left anchor with a
            // muted dot before the model-stack readout.
            if root.timer-active && root.session-name != "" : Text {
                text: root.session-name;
                font-size: 10px;
                font-weight: 600;
                color: Theme.success;
                vertical-alignment: center;
                horizontal-stretch: 0;
            }
            if root.timer-active && root.session-name != "" : Text {
                text: "·";
                font-size: 10px;
                color: Theme.text-muted;
                vertical-alignment: center;
                horizontal-stretch: 0;
            }
            // Active-stack and compact memory readout (read-only).
            VerticalLayout {
                horizontal-stretch: 0;
                alignment: center;

                Text {
                    text: root.active-stack + root.tok-per-sec;
                    font-size: 10px;
                    font-weight: 600;
                    color: Theme.accent;
                    vertical-alignment: center;
                }
                if root.app-memory != "" || root.mlx-memory != "" : HorizontalLayout {
                    spacing: 4px;

                    if root.app-memory != "" : Text {
                        text: @tr("App RAM") + " " + root.app-memory;
                        font-size: 10px;
                        color: Theme.text-muted;
                        vertical-alignment: center;
                    }
                    if root.mlx-memory != "" : Text {
                        text: "MLX" + " " + root.mlx-memory;
                        font-size: 10px;
                        color: Theme.text-muted;
                        vertical-alignment: center;
                    }
                }
            }
            // Source tag — "mic" green dot, "sys" cyan dot, "" gray. The dot is
            // colour-ONLY, so accessibility gets a word for the source it marks.
            Rectangle {
                width: 8px;
                height: 8px;
                y: (parent.height - self.height) / 2;
                border-radius: 4px;
                background: root.last-transcript-source == "mic"
                    ? Theme.success
                    : (root.last-transcript-source == "sys" ? Theme.accent : Theme.border-strong);
                accessible-role: text;
                accessible-label: root.last-transcript-source == "mic" ? @tr("Microphone")
                    : (root.last-transcript-source == "sys" ? @tr("System audio") : "");
            }
            // The live transcript text — elide when too long.
            Text {
                text: root.last-transcript-line == ""
                    ? @tr("waiting for transcript... (mic/sys → STT)")
                    : root.last-transcript-line;
                font-size: 11px;
                color: root.last-transcript-line == "" ? Theme.text-muted : Theme.text-secondary;
                overflow: elide;
                vertical-alignment: center;
                horizontal-stretch: 1;
            }
            // AI streaming pulse — visible when an ask is in flight.
            Rectangle {
                width: root.ai-streaming ? 80px : 0px;
                height: 18px;
                y: (parent.height - self.height) / 2;
                background: root.ai-streaming ? #818cf8.with-alpha(0.22) : transparent;
                border-color: #818cf8;
                border-width: root.ai-streaming ? 1px : 0px;
                border-radius: 9px;
                horizontal-stretch: 0;
                if root.ai-streaming : HorizontalLayout {
                    alignment: center;
                    spacing: 4px;
                    padding-left: 6px;
                    padding-right: 6px;
                    Image {
                        source: @image-url("../assets/icons/brain.svg");
                        colorize: #818cf8;
                        width: 12px;
                        height: 12px;
                        image-fit: contain;
                        vertical-alignment: center;
                    }
                    Text {
                        text: @tr("AI streaming");
                        font-size: 10px;
                        color: #818cf8;
                        vertical-alignment: center;
                    }
                }
            }
        }
        }

        // ===== Compact bar — narrow session strip =====
        // Per the «Glacier» redesign reference, compact is "the same bar with its
        // groups collapsed" (one window, the `compact` flag) — NOT a TTS reader.
        // It keeps the session status pill (drag handle) + the two key push-to-
        // record actions (спросить = your mic, захватить = system audio) + the
        // session timer + an Expand button, over the same live-status footer as
        // the full bar. The full action set returns on Expand. Read-aloud is
        // unaffected — the global Shift+Alt+1/2/3 hotkeys work regardless of this
        // layout (there is no on-bar Stop here, by design).
        if root.compact-bar && !root.bootstrap-mode : VerticalLayout {
            padding: 6px;
            spacing: 4px;

            // ── Action row: status (drag) · спросить · захватить · таймер · развернуть ──
            HorizontalLayout {
                padding-left: 2px;
                padding-right: 2px;
                spacing: 6px;

                // Status pill — DOUBLES AS DRAG HANDLE (same pattern as the full
                // bar: only the pill is the drag zone, so it can't shadow the
                // sibling buttons' TouchAreas). Tinted by the live session state.
                Rectangle {
                    background: (root.stealth-fault ? Theme.warning : root.status-color).with-alpha(0.18);
                    border-color: root.stealth-fault ? Theme.warning : root.status-color;
                    border-width: 1px;
                    border-radius: Metrics.radius-control;
                    height: 22px;
                    // Natural width like the full bar pill (NOT stretched) so the
                    // pill is the SAME length in both modes; the spring spacer
                    // below absorbs the slack and pushes Expand to the right edge.
                    horizontal-stretch: 0;
                    // Cap the pill so an unusually long / error status elides (…)
                    // instead of growing past the narrow 680px compact window and
                    // clipping the right-edge chips. Short statuses stay well under
                    // this, so the normal look is unchanged (full bar has 1280px,
                    // so it never needs the cap).
                    max-width: 150px;
                    // Same accessibility label as the full bar's pill (status +
                    // drag affordance) — zero layout impact.
                    accessible-role: text;
                    accessible-label: root.presented-status + ". " + @tr("Drag to move the bar; shows the live state");
                    TouchArea {
                        mouse-cursor: OverlayCursorPolicy.force-arrow ? default : grab;
                        pointer-event(ev) => {
                            if (ev.button == PointerEventButton.left
                                && ev.kind == PointerEventKind.down) {
                                root.drag-start-requested();
                            }
                        }
                        moved => {
                            if (self.pressed) { root.drag-moved(); }
                        }
                    }
                    HorizontalLayout {
                        // PIXEL-IDENTICAL to the full bar's status pill — same
                        // brand mark, grip, order and padding/spacing — so the
                        // left brand+grip block doesn't change at all on the
                        // compact toggle (no icon difference between modes).
                        padding-left: 4px;
                        padding-right: 8px;
                        spacing: 4px;
                        // Brand state mark — the SAME element the full bar uses
                        // (was a separate дуо icon; unified for zero visual diff;
                        // pulses on ai-streaming exactly like the full bar).
                        BrandStateMark {
                            assistant-active: root.ai-streaming;
                            mark-size: 22px;
                        }
                        // Grip — AFTER the brand mark, mirroring the full bar's
                        // [brand · grip · status] order (constraint #2: keep it).
                        IconSlot {
                            icon: @image-url("../assets/icons/grip.svg");
                            tint: Theme.accent;
                            glyph-size: 12px;
                            slot-width: 12px;
                            slot-height: 22px;
                        }
                        Text {
                            // I1/I4 — same translated stealth-failure override
                            // as the full bar's pill.
                            text: root.presented-status;
                            font-size: 11px;
                            font-weight: 600;
                            color: root.stealth-fault ? Theme.warning : root.status-color;
                            vertical-alignment: center;
                            // Elide a long status within the capped pill so it can
                            // never overflow the narrow compact window. Short
                            // statuses are well under the cap, so no visible change.
                            overflow: elide;
                            horizontal-stretch: 1;
                        }
                    }
                }

                // спросить — hold to record YOUR voice (mic) → STT → AI. Same
                // callbacks as the full bar's push-to-record button.
                RecordBtn {
                    icon: @image-url("../assets/icons/mic.svg");
                    has-icon: true;
                    label: @tr("ask");
                    accent: Theme.success;
                    recording: root.mic-recording;
                    pressed => { root.ptt-mic-pressed(); }
                    released => { root.ptt-mic-released(); }
                }
                // захватить — hold to record THEM (system audio) → STT → AI.
                RecordBtn {
                    icon: @image-url("../assets/icons/system-audio.svg");
                    has-icon: true;
                    label: @tr("grab");
                    accent: Theme.accent;
                    recording: root.sys-recording;
                    pressed => { root.ptt-sys-pressed(); }
                    released => { root.ptt-sys-released(); }
                }
                // Timer — start/stop the session; shows the running clock in session.
                Chip {
                    icon: root.timer-active
                        ? @image-url("../assets/icons/stop.svg")
                        : @image-url("../assets/icons/session-start.svg");
                    has-icon: true;
                    label: root.timer-active ? root.timer-label : @tr("start");
                    active: root.timer-active;
                    accent: #fbbf24;
                    mono: true;
                    clicked => { root.timer-toggle-clicked(); }
                }
                // ── Pause / Resume (v0.22.0) — only while a session runs.
                if root.timer-active : Chip {
                    icon: root.session-paused
                        ? @image-url("../assets/icons/play.svg")
                        : @image-url("../assets/icons/pause.svg");
                    has-icon: true;
                    a11y: root.session-paused ? "Resume the session" : "Pause the session";
                    active: root.session-paused;
                    accent: #fbbf24;
                    clicked => { root.pause-toggle-clicked(); }
                }
                // 🔒 Lock tiles (listening mode) — same toggle as the full bar; trembles
                // while active, turns red + still in the deep-lock state (v0.37).
                LockChip {
                    locked: root.suppress-tiles;
                    unlocked: root.lock-icon-unlocked;
                    deep: root.deep-lock;
                    a11y: root.lock-a11y;
                    managed: root.lock-menu-managed;
                    tight: true;
                    mode: root.deep-lock ? 2 : (root.suppress-tiles ? 1 : 0);
                    mode-selected(mode) => { root.lock-mode-selected(mode); }
                    menu-opened(x, y) => { root.lock-menu-opened(x, y); }
                }
                // Spring — absorbs the slack so the status pill stays natural-
                // width (identical to the full bar) and Expand sits at the right
                // edge, mirroring the full bar's window-control placement.
                Rectangle { horizontal-stretch: 1; min-width: 8px; }
                // RC4 — hide to tray, beside the Expand control (same action +
                // same icon as the full bar's hide chip).
                if root.tray-available : Chip {
                    icon: @image-url("../assets/icons/tray.svg");
                    has-icon: true;
                    a11y: @tr("Hide to tray");
                    accent: #38bdf8;
                    clicked => { root.hide-to-tray-clicked(); }
                }
                // Expand — restore the full bar (full action set).
                Chip {
                    icon: @image-url("../assets/icons/maximize.svg");
                    has-icon: true;
                    a11y: "Expand the bar";
                    accent: #38bdf8;
                    clicked => { root.compact-toggle-clicked(); }
                }
            }

            // ── Live-status footer — same readout as the full bar's bottom row. ──
            HorizontalLayout {
                padding-left: 4px;
                padding-right: 4px;
                spacing: 6px;
                Text {
                    text: root.active-stack + root.tok-per-sec;
                    font-size: 10px;
                    font-weight: 600;
                    color: Theme.accent;
                    overflow: elide;
                    vertical-alignment: center;
                    horizontal-stretch: 1;
                }
                Rectangle {
                    width: 8px;
                    height: 8px;
                    y: (parent.height - self.height) / 2;
                    border-radius: 4px;
                    background: root.last-transcript-source == "mic"
                        ? Theme.success
                        : (root.last-transcript-source == "sys" ? Theme.accent : Theme.border-strong);
                }
                Text {
                    text: root.last-transcript-line == ""
                        ? @tr("waiting for transcript... (mic/sys → STT)")
                        : root.last-transcript-line;
                    font-size: 11px;
                    color: root.last-transcript-line == "" ? Theme.text-muted : Theme.text-secondary;
                    overflow: elide;
                    vertical-alignment: center;
                    horizontal-stretch: 1;
                }
            }
        }

        // First honest production surface on macOS. The normal product bar is
        // hidden in this mode until its callbacks have real platform adapters.
        if root.bootstrap-mode : VerticalLayout {
            padding: Metrics.space-sm;
            spacing: 4px;

            HorizontalLayout {
                spacing: Metrics.space-md;

                Rectangle {
                    horizontal-stretch: 1;
                    accessible-role: text;
                    accessible-label: @tr("Suflyor for macOS") + ". "
                        + @tr("Native overlay ready; product features are being connected.");
                    TouchArea {
                        mouse-cursor: grab;
                        pointer-event(ev) => {
                            if (ev.button == PointerEventButton.left
                                && ev.kind == PointerEventKind.down) {
                                root.drag-start-requested();
                            }
                        }
                    }
                    HorizontalLayout {
                        spacing: Metrics.space-sm;
                        BrandStateMark { mark-size: 26px; }
                        VerticalLayout {
                            alignment: center;
                            Text {
                                text: @tr("Suflyor for macOS");
                                color: Theme.text-primary;
                                font-size: Metrics.font-body;
                                font-weight: 700;
                            }
                            Text {
                                text: @tr("Native overlay ready; product features are being connected.");
                                color: Theme.text-secondary;
                                font-size: Metrics.font-label;
                                overflow: elide;
                            }
                        }
                    }
                }

                // The only product controls with real macOS adapters so far.
                Chip {
                    label: root.mic-permission-state == 3
                        ? (root.mic-capture-state == 1 ? @tr("Mic live")
                        : (root.mic-capture-state == 2 ? @tr("Mic failed") : @tr("Start mic")))
                        : (root.mic-permission-state == 4 ? @tr("Requesting...")
                        : ((root.mic-permission-state == 1 || root.mic-permission-state == 2)
                        ? @tr("Mic denied") : @tr("Allow mic")));
                    a11y: self.label;
                    height: 24px;
                    active: root.mic-capture-state == 1;
                    accent: (root.mic-permission-state == 1 || root.mic-permission-state == 2)
                        || root.mic-capture-state == 2 ? Theme.danger
                        : (root.mic-capture-state == 1 ? Theme.success : Theme.accent);
                    accessible-action-default => { root.mic-toggle-clicked(); }
                    clicked => { root.mic-toggle-clicked(); }
                }
                Chip {
                    label: @tr("Ask");
                    height: 24px;
                    accessible-action-default => { root.text-ask-clicked(); }
                    clicked => { root.text-ask-clicked(); }
                }
                Chip {
                    label: @tr("AI setup");
                    height: 24px;
                    accessible-action-default => { root.open-settings-clicked(); }
                    clicked => { root.open-settings-clicked(); }
                }

                Chip {
                    label: @tr("Quit");
                    accent: Theme.danger;
                    height: 24px;
                    accessible-action-default => { root.quit-confirm(); }
                    clicked => { root.quit-confirm(); }
                }
            }

            // One compact transcript/status row — the same latest-line
            // readout the normal bars show (dot = source tag, text = the
            // newest STT line; the placeholder stays until the first line).
            HorizontalLayout {
                padding-left: 4px;
                padding-right: 4px;
                spacing: 6px;
                Rectangle {
                    width: 8px;
                    height: 8px;
                    y: (parent.height - self.height) / 2;
                    border-radius: 4px;
                    background: root.last-transcript-source == "mic"
                        ? Theme.success
                        : (root.last-transcript-source == "sys" ? Theme.accent : Theme.border-strong);
                }
                Text {
                    text: root.last-transcript-line == ""
                        ? @tr("waiting for transcript... (mic/sys → STT)")
                        : root.last-transcript-line;
                    font-size: 11px;
                    color: root.last-transcript-line == "" ? Theme.text-muted : Theme.text-secondary;
                    overflow: elide;
                    vertical-alignment: center;
                    horizontal-stretch: 1;
                }
            }
        }
    }
}

property <string> presented-status: root.stealth-fault
        ? @tr("[!] stealth unavailable")
        : root.status-text;

