component TextAskWindow inherits Window {
    no-frame: true;
    always-on-top: true;
    title: @tr("suflyor text ask (Slint)");
    default-font-family: Theme.font-sans;
    background: Theme.bg-surface;
    preferred-width: 480px;
    preferred-height: 112px;

    in-out property <string> query;
    // v0.10.1 — the active profile/persona label (set live by the host on open),
    // so the user can see which profile will shape the typed answer.
    in-out property <string> active-profile;
    // Emitted with the typed text when the user presses Enter / clicks Send.
    callback submitted(string);
    // Emitted on Esc — the host hides + drops the window.
    callback cancelled();
    // ТЗ 2026-07-06 (C) — frameless drag (cursor-delta, same as help/wizard):
    // the header row is the handle; the host persists the position on close.
    callback drag-start-requested();
    callback drag-moved();

    forward-focus: input;

    function fire() {
        if (root.query != "") {
            root.submitted(root.query);
            root.query = "";
        }
    }

    FocusScope {
        // Esc cancels; everything else falls through to the focused LineEdit.
        key-pressed(e) => {
            if (e.text == Key.Escape) {
                root.cancelled();
                return accept;
            }
            // Layout-independent editing shortcuts. Slint's built-in Ctrl+A/C/V/X
            // are keyed on the Latin chars a/c/v/x (i-slint-core `shortcut()`), so
            // under a Cyrillic layout the physical keys emit ф/с/м/ч and the
            // shortcuts silently die. Match those and call the LineEdit's own
            // functions (cursor/selection-aware). "ф/с/м/ч" are keycode matches,
            // not UI strings — deliberately not @tr.
            if (e.modifiers.control && !e.modifiers.shift) {
                if (e.text == "м" || e.text == "М") { input.paste(); return accept; }
                if (e.text == "с" || e.text == "С") { input.copy(); return accept; }
                if (e.text == "ч" || e.text == "Ч") { input.cut(); return accept; }
                if (e.text == "ф" || e.text == "Ф") { input.select-all(); return accept; }
            }
            return reject;
        }
        VerticalLayout {
            padding: 14px;
            spacing: 10px;
            HorizontalLayout {
                spacing: Metrics.space-sm;   // was 8px
                // ТЗ 2026-07-06 (C) — drag handle BEHIND the header content
                // (help.slint pattern): the TouchArea drags; the CloseButton
                // stays a sibling on top so its clicks are its own.
                Rectangle {
                    horizontal-stretch: 1;
                    height: 30px;
                    TouchArea {
                        mouse-cursor: grab;
                        pointer-event(ev) => {
                            if (ev.button == PointerEventButton.left
                                && ev.kind == PointerEventKind.down) {
                                root.drag-start-requested();
                            }
                        }
                        moved => {
                            if (self.pressed) { root.drag-moved(); }
                        }
                    }
                    HorizontalLayout {
                        spacing: Metrics.space-sm;
                        Rectangle {
                            width: 18px;
                            height: 30px;
                            IconSlot {
                                y: 6px;
                                icon: @image-url("../assets/icons/pencil.svg");
                                tint: Theme.accent;
                                glyph-size: 15px;
                                slot-size: 18px;
                            }
                        }
                        Rectangle {
                            width: 13px;
                            height: 30px;
                            DragGrip { y: 2px; }
                        }
                        Text {
                            text: @tr("Write a question for the assistant");
                            color: Theme.text-secondary;
                            font-size: Metrics.font-body;   // was 12px
                            font-weight: 600;
                            vertical-alignment: center;
                        }
                        // v0.10.1 — active profile/persona (applies to the typed
                        // answer too, identically to voice). Right-aligned, muted.
                        Text {
                            text: root.active-profile;
                            color: Theme.text-muted;
                            font-size: 11px;
                            vertical-alignment: center;
                            horizontal-alignment: right;
                            horizontal-stretch: 1;
                            overflow: elide;
                        }
                    }
                }
                // V0.8.4 — explicit close (= Esc). Shared CloseButton.
                CloseButton {
                    clicked => { root.cancelled(); }
                }
            }
            HorizontalLayout {
                spacing: Metrics.space-sm;   // was 8px
                input := LineEdit {
                    placeholder-text: @tr("Type your question…");
                    text <=> root.query;
                    accepted => { root.fire(); }
                }
                Button {
                    text: @tr("Send");
                    primary: true;
                    clicked => { root.fire(); }
                }
            }
        }
    }
}

global Theme {
    in-out property <int> scheme: 0;
    out property <bool> is-light: scheme == 3;

    // ---- Surfaces ----
    // bg-base: deepest window backdrop · bg-surface: bar/tiles/panels ·
    // bg-elevated: dropdowns, active row, hover.
    out property <color> bg-base: scheme == 1 ? #131210 : scheme == 2 ? #0B0D14 : scheme == 3 ? #EEF1F5 : #0D1117;
    out property <color> bg-surface: scheme == 1 ? #1C1A17 : scheme == 2 ? #12141F : scheme == 3 ? #F7F9FB : #151B23;
    out property <color> bg-elevated: scheme == 1 ? #272320 : scheme == 2 ? #1B1E2D : scheme == 3 ? #FFFFFF : #1E2530;

    // ---- Text ----
    out property <color> text-primary: scheme == 1 ? #F1ECE3 : scheme == 2 ? #EAEAF5 : scheme == 3 ? #16202B : #E8EEF4;
    out property <color> text-secondary: scheme == 1 ? #C0B8AC : scheme == 2 ? #B4B6CC : scheme == 3 ? #3E4A57 : #B3BECA;
    out property <color> text-muted: scheme == 1 ? #948C7F : scheme == 2 ? #888BA6 : scheme == 3 ? #566270 : #8893A0;

    // ---- Accent ----
    out property <color> accent: scheme == 1 ? #2DD4BF : scheme == 2 ? #A98BFA : scheme == 3 ? #1A63CC : #4C8DFF;
    out property <color> accent-hover: scheme == 1 ? #4FE3CF : scheme == 2 ? #C0A8FF : scheme == 3 ? #134FA6 : #6FA3FF;
    // Redesign «Glacier»: legible text/glyph colour ON an accent FILL (filled
    // buttons, badges). Hand-picked per scheme for WCAG-AA on THAT accent:
    // the bright teal/violet (schemes 1/2) and the mid Glacier blue (default)
    // are light enough to want DARK text; the darker Light-Frost blue (scheme 3)
    // wants near-white.
    out property <color> on-accent: scheme == 1 ? #0A0906 : scheme == 2 ? #06070E : scheme == 3 ? #F7F9FB : #06101F;
    // Redesign «Glacier»: tinted-accent SURFACE for active / selected rows,
    // chips, badges (~12-15% accent over that scheme's bg-surface, as a fixed
    // literal so contrast stays controlled — replaces ad-hoc accent.with-alpha).
    out property <color> accent-subtle: scheme == 1 ? #15211D : scheme == 2 ? #1F1D30 : scheme == 3 ? #DCE7F5 : #13233D;

    // ---- Statuses (recognisable across all schemes) ----
    out property <color> success: scheme == 1 ? #4ABE6E : scheme == 2 ? #3FB97A : scheme == 3 ? #1E7E3C : #3FB950;
    out property <color> warning: scheme == 1 ? #E6B53C : scheme == 2 ? #E3B341 : scheme == 3 ? #8A5A00 : #E3B341;
    out property <color> danger: scheme == 1 ? #F26157 : scheme == 2 ? #F0596B : scheme == 3 ? #C7362F : #F85149;

    // ---- Borders ----
    out property <color> border: scheme == 1 ? #2E2A25 : scheme == 2 ? #24273A : scheme == 3 ? #D4DAE1 : #283039;
    out property <color> border-strong: scheme == 1 ? #423D36 : scheme == 2 ? #353953 : scheme == 3 ? #B7C0CA : #3A4552;

    // ---- Code blocks + popup scrim (8-digit hex = #RRGGBBAA) ----
    out property <color> code-bg: scheme == 1 ? #0E0D0A : scheme == 2 ? #07080E : scheme == 3 ? #EDEFF2 : #090C10;
    out property <color> code-text: scheme == 1 ? #D6CFC4 : scheme == 2 ? #CACBE0 : scheme == 3 ? #1E2730 : #CAD4DE;
    out property <color> scrim: scheme == 1 ? #0A09079E : scheme == 2 ? #06070EA3 : scheme == 3 ? #141C284C : #070A0E9E;

    // ---- Typography ----
    // The design handoff recommends IBM Plex Sans/Mono, but those aren't
    // installed on the target box and bundling .ttf is deferred. We use the
    // best already-installed pair with full Cyrillic coverage instead:
    // Segoe UI (the Windows system sans) + Cascadia Mono (ships with Windows
    // Terminal / VS). Both render Russian cleanly with zero download. Swap
    // these two strings if IBM Plex (or Golos Text + JetBrains Mono) ever gets
    // bundled — every text element routes through these roles.
    out property <string> font-sans: "Segoe UI";
    out property <string> font-mono: "Cascadia Mono";
}

struct MarkdownBlock {
    kind: int,
    text: string,
    display-text: string,
    lang: string,
    // A2 (ТЗ 2026-07-02) — quiet per-block mark for «⭐ В память»; toggled via Rust
    // (toggle-block-marked), reset with the model on each stream re-render.
    marked: bool,
}

component StarMark inherits Rectangle {
    in property <bool> marked;
    // P5: carries whether SHIFT was held, for range-marking. `clicked` gives no modifiers, so latch
    // the shift state on pointer-DOWN and fire it on `clicked` — this keeps proper click semantics
    // (fires only on down+up BOTH in-area; a drag-release-outside or a cancel does NOT toggle).
    callback clicked(bool /* shift */);
    width: 20px;
    ta := TouchArea {
        property <bool> shift-latched;
        pointer-event(e) => {
            if (e.kind == PointerEventKind.down) {
                self.shift-latched = e.modifiers.shift;
            }
        }
        clicked => { root.clicked(self.shift-latched); }
    }
    Image {
        source: @image-url("../assets/icons/star.svg");
        colorize: root.marked ? Theme.accent : Theme.text-muted;
        opacity: root.marked ? 1.0 : (ta.has-hover ? 1.0 : 0.35);
        width: 13px;
        height: 13px;
        image-fit: contain;
        x: (parent.width - self.width) / 2;
        y: (parent.height - self.height) / 2;
    }
}

