component TileWindow inherits Window {
    // Phase 4 — keep std-widgets (follow-up LineEdit, ScrollView) dark with
    // the active scheme instead of Slint's light fluent default.
    property <bool> widgets-light: Theme.is-light;
    init => { Palette.color-scheme = root.widgets-light ? ColorScheme.light : ColorScheme.dark; }
    changed widgets-light => { Palette.color-scheme = root.widgets-light ? ColorScheme.light : ColorScheme.dark; }
    title: @tr("tile");
    icon: @image-url("../assets/icon.svg");
    background: transparent;
    no-frame: true;
    always-on-top: true;
    preferred-width: 460px;
    preferred-height: 360px;
    // 360 (was 320): the header's fixed-width control cluster (copy/more/speak/maximize/close)
    // + a capped source-label must fit so Close never clips even at the narrowest size.
    min-width: 360px;
    min-height: 200px;

    in-out property <string> tile-title: "Untitled tile";
    in-out property <int> sequence: 0;
    in-out property <[MarkdownBlock]> blocks: [];
    // Source label shown in chrome row (e.g. "ai", "kb", "snippet").
    in-out property <string> source-label: "—";
    // Phase E6 v12 — trigger badge.
    in-out property <string> trigger-label: "";
    in-out property <color> trigger-color: Theme.accent;
    // Phase E6 v17 — pinned bool: changes pin button visual; Rust
    // toggles on click. Maximize bool: Rust resizes window via Win32.
    in-out property <bool> pinned: false;
    in-out property <bool> tile-maximized: false;
    // Phase E6 v20 — body opacity (0.5..1.0). Lets the user see
    // through tiles to the meeting window underneath. Wired to
    // cfg.tile_body_opacity via Settings → Stealth slider.
    // Cherry-picked from Anthropic design bundle 2 (only this prop;
    // no other design changes — see chat thread cycle 26).
    in-out property <float> body-opacity: 1.0;
    // Phase E6 v45 (continue-dialog) — conversation key for this tile.
    // >= 0 means the tile supports follow-up questions (the input row at
    // the bottom is shown). -1 = no dialog (KB / snippet / auto tiles).
    in-out property <int> convo-id: -1;
    // Synchronous per-tile id (set at creation) — the abort-registry key, so a
    // closed/evicted tile can cancel its in-flight AI request even before its
    // HWND is realized (the HWND grab is deferred, which is why keying on it
    // silently lost the registration and aborts missed under spam).
    in-out property <int> tile-id: -1;
    // True while an answer is streaming — disables the follow-up input.
    in-out property <bool> followup-busy: false;
    // V5 — true while the 🎤 voice follow-up is recording the mic (toggles the
    // send-row glyph to ⏹). Driven from Rust (wire_voice_followup).
    in-out property <bool> voice-recording: false;
    // V5 — show the 🔄 regenerate button (vision tiles: re-run the screenshot
    // query for a longer / different answer).
    in-out property <bool> can-regenerate: false;
    // V0.8.0 (Поток D) — show the 🧠 "ask the smart cloud model" button. Re-runs
    // the same question on the cloud model (deeper reasoning) when the local
    // answer was too weak — one-shot, without changing the default provider.
    in-out property <bool> can-escalate: false;
    // V0.8.3 — copy the answer to the clipboard. `can-copy` shows the button
    // (set on conversational tiles); `copied` briefly flips to a check icon.
    in-out property <bool> can-copy: false;
    in-out property <bool> copied: false;
    // C (ТЗ 2026-07-02) — per-code-block copy: index of the code block whose 📋
    // just fired (its icon flips to a check for ~1.5s); -1 = none. Rust-driven,
    // mirroring `copied` above.
    in-out property <int> copied-block-index: -1;
    // A2 (ТЗ 2026-07-02, редизайн) — «⭐ В память»: quiet per-block MARK (toggle),
    // then one bottom «В память (N)» panel. marked-count = how many blocks are marked
    // (Rust-maintained); capture-text = the edit buffer shown only when exactly one is
    // marked (trim-before-save). Each block carries its own `marked`.
    in-out property <int> marked-count: 0;
    // P5: last plain-clicked block index — the anchor a SHIFT+click range-marks up to. A Slint prop
    // (not Rust-only state) so `changed blocks` resets it WITH the marks below — a streaming model
    // swap then can't leave a stale anchor that mis-marks a range on the fresh answer.
    in-out property <int> mark-anchor: -1;
    in-out property <string> capture-text: "";
    // Which single block `capture-text` was seeded from (-1 = none). Lets an
    // in-progress edit survive marking/un-marking OTHER blocks — Rust re-seeds only
    // when the sole-marked block actually changes (review I-1).
    in-out property <int> capture-block-index: -1;
    // P5 (ТЗ 2026-07-03): the bool is whether SHIFT was held. Shift+click range-marks from the
    // last plain-clicked anchor to this block; a plain click toggles + re-anchors. The range/anchor
    // logic lives in Rust (it owns the blocks model) — this just forwards the modifier.
    callback toggle-block-marked(int, bool);
    callback save-marked();
    callback clear-marks();
    // P5 — «Копировать» on the mark bar: copy every marked block's text to the clipboard (marks stay).
    callback copy-marked();
    // ТЗ 2026-07-03 — mouse-selection capture: a right-click «Add selection to memory»
    // on any block raises `capture-pending` and seeds `capture-text` with the selected
    // span (Rust slices block.text by the selection's byte offsets) → the bottom editor
    // bar opens for trim-before-save, independent of the per-block ⭐ marks.
    in-out property <bool> capture-pending: false;
    // (block-index, anchor-byte-offset, cursor-byte-offset) of the right-click selection.
    callback capture-selection(int, int, int);
    // Save the pending selection (edited `capture-text`) as one approved note; discard it.
    callback save-capture();
    callback cancel-capture();
    // R1 (retest v0.28.0) — «Выделить текст» mode restored: swaps the per-block body for ONE
    // SelectableText holding the whole (joined, capped) answer, so text can be dragged / copied /
    // ⭐-captured ACROSS blocks (per-block TextInputs are separate selection islands — Slint can't
    // span them). `select-text` is built in Rust. The overflow that got it deleted was the
    // ContextMenuArea-collapse paint bug, since fixed in SelectableText (Rectangle root).
    in-out property <bool> select-mode: false;
    in-out property <string> select-text: "";
    callback toggle-select-mode();
    // Stale-marker guard: streaming re-renders REPLACE the blocks model on every delta
    // (fresh blocks come with marked=false), so clear the copied-check AND the
    // marked-count on any model swap. A settled answer fires no further set_blocks.
    changed blocks => { root.copied-block-index = -1; root.marked-count = 0; root.mark-anchor = -1; root.capture-block-index = -1; root.capture-text = ""; root.capture-pending = false; root.select-mode = false; }
    // v0.18.6 — «Повторить»: shown on a summary-failure tile that carries a
    // session id. Resumes the summary from the persisted conspect (re-maps only
    // the failed parts, then re-runs the reduce) — see retry_meeting_summary.
    in-out property <bool> can-retry: false;
    // Read-aloud (TTS): show the speaker + pause/resume controls on a tile whose
    // text can be spoken (OCR / answer / summary). `speak-paused` flips the
    // second button's icon between pause (playing) and play (paused).
    in-out property <bool> can-speak: false;
    in-out property <bool> speak-active: false;
    in-out property <bool> speak-paused: false;
    in-out property <bool> speak-loading: false;
    in-out property <bool> speak-error: false;
    // Tile-player speed follows the process-global read speed across tiles.
    in-out property <string> speak-speed-label: "1.0x";
    // Bound to the follow-up LineEdit so do-submit() can read + clear it.
    in-out property <string> followup-text;

    callback close-clicked();
    callback pin-clicked();
    callback maximize-clicked();
    // V5 — re-run the last request and replace the answer (item 4).
    callback regenerate-clicked();
    // V0.8.0 (Поток D) — re-run the same question on the smart cloud model.
    callback escalate-clicked();
    // V0.8.3 — copy the answer text to the clipboard (Rust flashes a check icon).
    callback copy-clicked();
    // C (ТЗ 2026-07-02) — copy ONE fenced code block: (block-index, clean code).
    callback copy-block-clicked(int, string);
    // v0.18.6 — retry a failed meeting summary from its persisted conspect.
    callback retry-clicked();
    // Read-aloud — speak the tile's text aloud / toggle pause-resume.
    callback speak-clicked();
    callback speak-pause-clicked();
    callback speak-seek-clicked(int);
    callback speak-speed-next-clicked();
    // Phase E6 v22 — manual cursor-delta drag. drag-start-requested
    // fires on pointer-down (records anchor), drag-moved fires on
    // each move while pressed (moves window by delta). Replaces the
    // old WM_NCLBUTTONDOWN modal drag that left TouchArea stuck.
    callback drag-start-requested();
    callback drag-moved();
    // Phase E6 v45 — user submitted a follow-up question (the text).
    callback followup-submitted(string);
    // V5 — user toggled the 🎤 voice follow-up (start/stop mic recording);
    // Rust records → transcribes → submits the recognized text as a follow-up.
    callback followup-voice-toggled();

    // Guarded submit shared by the input's Enter + the send button. No-op
    // while busy or empty; clears the field after firing.
    function do-submit() {
        if (root.followup-busy) {
            return;
        }
        if (root.followup-text == "") {
            return;
        }
        root.followup-submitted(root.followup-text);
        root.followup-text = "";
    }

    Rectangle {
        // Near-opaque (was 0.92): at 8% see-through a tile CASCADED behind this
        // one bled its text through as faint ghosting over the answer (user's
        // screenshot). 0.98 kills the visible bleed but keeps a hint of depth;
        // the body-opacity slider below still gives an INTENTIONAL fade.
        background: Theme.bg-surface.with-alpha(0.98);
        border-radius: Metrics.radius-control;
        border-width: Metrics.border-thin;
        border-color: Theme.border;
        opacity: root.body-opacity;

        VerticalLayout {
            padding: Metrics.space-md;
            spacing: Metrics.space-sm;

            // ===== Chrome row =====
            // Phase E6 v8 — RESTRUCTURED to fix the "pin/X buttons
            // don't fire" bug. The previous version wrapped a
            // TouchArea over the WHOLE chrome row, which captured
            // pointer events even when they overlapped the Button
            // widgets → Button.clicked never fired (TouchArea
            // pointer-event swallows). Now the TouchArea is INSIDE
            // a sub-Rectangle that only covers the title+spacer
            // region; buttons live OUTSIDE that Rectangle so their
            // internal TouchArea is the only one in the click path.
            HorizontalLayout {
                spacing: Metrics.space-sm;
                height: 30px;
                // Title + drag-handle area — stretches to fill
                // remaining width on the LEFT of the source-label +
                // buttons cluster. TouchArea covers ONLY this area
                // so its pointer-event capture doesn't shadow the
                // sibling Button widgets.
                Rectangle {
                    horizontal-stretch: 1;
                    drag-area := TouchArea {
                        mouse-cursor: grab;
                        pointer-event(ev) => {
                            if (ev.button == PointerEventButton.left
                                && ev.kind == PointerEventKind.down) {
                                root.drag-start-requested();
                            }
                        }
                        moved => {
                            if (self.pressed) { root.drag-moved(); }
                        }
                    }
                    DragGrip {
                        x: 0;
                        y: (parent.height - self.height) / 2;
                    }
                    Text {
                        x: 17px;
                        text: @tr("#{}  {}", root.sequence, root.tile-title);
                        font-size: Metrics.font-body;
                        font-weight: 700;
                        color: Theme.text-primary;
                        vertical-alignment: center;
                        overflow: elide;
                        width: parent.width - 17px;
                    }
                }
                if root.source-label != "" : Rectangle {
                    background: transparent;
                    border-color: Theme.border-strong;
                    border-width: 1px;
                    border-radius: 8px;
                    height: 20px;
                    horizontal-stretch: 0;
                    // Cap + elide: a long source-label (e.g. a full local-model .gguf path)
                    // must NOT push the fixed-width header buttons — including Close — off the
                    // right edge. Bounded here so the window controls always stay visible.
                    max-width: 150px;
                    HorizontalLayout {
                        padding-left: 6px;
                        padding-right: 6px;
                        Text {
                            text: root.source-label;
                            font-size: 10px;
                            color: Theme.text-muted;
                            vertical-alignment: center;
                            overflow: elide;
                        }
                    }
                }
                // Phase E6 v9 — wrap buttons in fixed-min-width Rectangles
                // with explicit TouchArea so the click target is larger
                // than the default Slint Button intrinsic width. User
                // reported "X не работает" on dragged tiles — root
                // cause was pixel-perfect aim required (button ~15 px
                // wide). Now each button is 44 px wide + 28 px tall so
                // off-by-a-few-pixels clicks still land on the button.
                // Pin button removed (audit #135): the `pinned` flag never
                // actually protected a tile from "close all" / the live-tile
                // cap, so the button was a misleading no-op. The property +
                // pin-clicked callback stay declared (Rust handlers reference
                // them) but are now inert.
                // Phase E6 v17 — Maximize button. User: "нет
                // функционала развернуть, нужно отдельной кнопкой
                // или даб-кликом". Win32 SetWindowPos resizes window
                // 460x360 → 800x600 (toggle).
                // V0.8.3 — copy the answer text to the clipboard.
                // Shown on conversational tiles (can-copy).
                if root.can-copy: Rectangle {
                    width: 30px;
                    height: 30px;
                    background: copy-touch.has-hover ? Theme.border-strong : Theme.border;
                    border-radius: 6px;
                    border-width: 1px;
                    border-color: Theme.border-strong;
                    accessible-role: button;
                    accessible-label: root.copied ? @tr("copied") : @tr("Copy");
                    copy-touch := TouchArea {
                        clicked => { root.copy-clicked(); }
                    }
                    Image {
                        source: root.copied
                            ? @image-url("../assets/icons/check.svg")
                            : @image-url("../assets/icons/copy.svg");
                        colorize: root.copied ? Theme.success : Theme.text-secondary;
                        width: 16px;
                        height: 16px;
                        image-fit: contain;
                        x: (parent.width - self.width) / 2;
                        y: (parent.height - self.height) / 2;
                    }
                }
                // «⋯» overflow — 🔄 regenerate + 🧠 escalate moved off the
                // always-on header into a popup menu (Glacier Этап 6). The button
                // shows only when at least one is available; the callbacks and the
                // followup-busy guards are unchanged.
                Rectangle {
                    width: 30px;
                    height: 30px;
                    background: more-touch.has-hover ? Theme.border-strong : Theme.border;
                    border-radius: 6px;
                    border-width: 1px;
                    border-color: Theme.border-strong;
                    // Icon-only overflow — a word for accessibility instead of
                    // just the ⋯ glyph.
                    accessible-role: button;
                    accessible-label: @tr("More actions");
                    more-touch := TouchArea {
                        clicked => { overflow-popup.show(); }
                    }
                    Image {
                        source: @image-url("../assets/icons/more.svg");
                        colorize: Theme.text-secondary;
                        width: 16px;
                        height: 16px;
                        image-fit: contain;
                        x: (parent.width - self.width) / 2;
                        y: (parent.height - self.height) / 2;
                    }
                    overflow-popup := PopupWindow {
                        // Right-align the 168px menu under the 30px button, just
                        // below the header row.
                        x: 30px - 168px;
                        y: parent.height + 4px;
                        Rectangle {
                            width: 168px;
                            background: Theme.bg-elevated;
                            border-color: Theme.border-strong;
                            border-width: 1px;
                            border-radius: 8px;
                            VerticalLayout {
                                padding: 4px;
                                spacing: 2px;
                                // R1 (retest v0.28.0) — toggle whole-answer «Выделить текст» mode.
                                TileMenuRow {
                                    icon: @image-url("../assets/icons/select-text.svg");
                                    label: root.select-mode ? @tr("Rich view") : @tr("Select text");
                                    clicked => {
                                        root.toggle-select-mode();
                                        overflow-popup.close();
                                    }
                                }
                                if root.can-regenerate: TileMenuRow {
                                    icon: @image-url("../assets/icons/refresh.svg");
                                    label: @tr("Regenerate");
                                    // Fire the action FIRST, then close — calling
                                    // close() before the callback tears down the
                                    // popup subtree and drops the rest of the
                                    // handler (Slint PopupWindow gotcha).
                                    clicked => {
                                        if (!root.followup-busy) {
                                            root.regenerate-clicked();
                                        }
                                        overflow-popup.close();
                                    }
                                }
                                if root.can-escalate: TileMenuRow {
                                    icon: @image-url("../assets/icons/brain.svg");
                                    label: @tr("Smart cloud");
                                    clicked => {
                                        if (!root.followup-busy) {
                                            root.escalate-clicked();
                                        }
                                        overflow-popup.close();
                                    }
                                }
                            }
                        }
                    }
                }
                // v0.18.6 — «Повторить» on a summary-failure tile. Accent-colored
                // so it reads as the primary action (the body text says «…и
                // попробуйте ещё раз»). Resumes from the persisted conspect.
                if root.can-retry: Rectangle {
                    width: 30px;
                    height: 30px;
                    background: retry-touch.has-hover ? Theme.border-strong : Theme.border;
                    border-radius: 6px;
                    border-width: 1px;
                    border-color: Theme.border-strong;
                    accessible-role: button;
                    accessible-label: @tr("Retry");
                    retry-touch := TouchArea {
                        clicked => { root.retry-clicked(); }
                    }
                    Image {
                        source: @image-url("../assets/icons/refresh.svg");
                        colorize: Theme.accent;
                        width: 16px;
                        height: 16px;
                        image-fit: contain;
                        x: (parent.width - self.width) / 2;
                        y: (parent.height - self.height) / 2;
                    }
                }
                // Read-aloud — 🔊 speak the tile text aloud; ⏯ pause/resume.
                if root.can-speak: Rectangle {
                    width: 30px;
                    height: 30px;
                    background: speak-touch.has-hover ? Theme.border-strong : Theme.border;
                    border-radius: 6px;
                    border-width: 1px;
                    border-color: Theme.border-strong;
                    accessible-role: button;
                    accessible-label: root.speak-active ? @tr("Stop reading aloud") : @tr("Read aloud");
                    speak-touch := TouchArea {
                        clicked => { root.speak-clicked(); }
                    }
                    Image {
                        source: root.speak-active
                            ? @image-url("../assets/icons/stop.svg")
                            : @image-url("../assets/icons/voice.svg");
                        colorize: root.speak-active ? Theme.danger : Theme.text-secondary;
                        width: 16px;
                        height: 16px;
                        image-fit: contain;
                        x: (parent.width - self.width) / 2;
                        y: (parent.height - self.height) / 2;
                    }
                }
                Rectangle {
                    width: 30px;
                    height: 30px;
                    background: max-touch.has-hover ? Theme.border-strong : Theme.border;
                    border-radius: 6px;
                    border-width: 1px;
                    border-color: Theme.border-strong;
                    accessible-role: button;
                    accessible-label: root.tile-maximized ? @tr("Restore tile size") : @tr("Maximize tile");
                    max-touch := TouchArea {
                        clicked => { root.maximize-clicked(); }
                    }
                    Image {
                        source: root.tile-maximized
                            ? @image-url("../assets/icons/restore.svg")
                            : @image-url("../assets/icons/maximize.svg");
                        colorize: Theme.text-primary;
                        width: 16px;
                        height: 16px;
                        image-fit: contain;
                        x: (parent.width - self.width) / 2;
                        y: (parent.height - self.height) / 2;
                    }
                }
                CloseButton {
                    box: 30px;
                    glyph: 16px;
                    clicked => { root.close-clicked(); }
                }
            }

            Rectangle {
                background: Theme.border;
                height: 1px;
            }

            if root.speak-error : Text {
                text: @tr("Read-aloud is unavailable. Check the installed voice and try again.");
                font-size: 11px;
                color: Theme.danger;
                wrap: word-wrap;
            }

            // ===== Trigger badge =====
            // Phase E6 v12 — colored pill below chrome row shows what
            // detector trigger spawned this tile (Keyword "docker",
            // Question "...", every-line). Hidden when trigger-label
            // is empty (manual F9 ask or F6 spawn).
            if root.trigger-label != "" : Rectangle {
                height: 22px;
                horizontal-stretch: 1;
                HorizontalLayout {
                    alignment: start;
                    Rectangle {
                        background: root.trigger-color.with-alpha(0.18);
                        border-color: root.trigger-color;
                        border-width: 1px;
                        border-radius: 9px;
                        height: 20px;
                        horizontal-stretch: 0;
                        HorizontalLayout {
                            padding-left: 8px;
                            padding-right: 8px;
                            Text {
                                text: root.trigger-label;
                                font-size: 10px;
                                font-weight: 700;
                                color: root.trigger-color;
                                vertical-alignment: center;
                            }
                        }
                    }
                }
            }

            // ===== Markdown body (kind-discriminant renderer) =====
            // Phase E6 fix — viewport-width and explicit Text width
            // force `wrap: word-wrap` to actually engage. Without the
            // viewport-width hint, ScrollView lets content render
            // unconstrained → long Russian paragraphs overflowed the
            // dark fill area (user complaint "текст выходит за края").
            if !root.select-mode : ScrollView {
                vertical-stretch: 1;
                horizontal-stretch: 1;
                viewport-width: self.width;
                min-height: 0px; // RS2: scroll inside the fixed tile, never grow the window (see below)
                VerticalLayout {
                    spacing: Metrics.space-xs;
                    // Keep the final answer block scrollable above the fixed player.
                    padding-bottom: root.speak-active ? 44px : 0px;
                    // A2 fix (retest r2): right inset so the per-block ⭐ gutter clears the
                    // ScrollView scrollbar on long/scrolling answers (tester: the stars
                    // "compete with the scroll" and get hard to click).
                    padding-right: 14px;
                    // Per-block wrapper is a LAYOUT, not a bare Rectangle.
                    // A Rectangle does NOT size its height to non-layout
                    // children, so long Text blocks collapsed to ~0px and
                    // painted on top of the next block. A VerticalLayout
                    // sizes to its one active child → blocks stack cleanly.
                    // User: "текст наслаивается друг на друге".
                    for block[i] in root.blocks: VerticalLayout {

                        // H1
                        if block.kind == 1 : SelectableText {
                            text: block.display-text;
                            source-text: block.text;
                            font-size: Metrics.font-heading;
                            font-weight: 700;
                            text-color: Theme.text-primary;
                            wrap: word-wrap;
                            capture(a, c) => { root.capture-selection(i, a, c); }
                        }
                        // H2
                        if block.kind == 2 : SelectableText {
                            text: block.display-text;
                            source-text: block.text;
                            font-size: 15px;
                            font-weight: 700;
                            text-color: Theme.text-secondary;
                            wrap: word-wrap;
                            capture(a, c) => { root.capture-selection(i, a, c); }
                        }
                        // H3
                        if block.kind == 3 : SelectableText {
                            text: block.display-text;
                            source-text: block.text;
                            font-size: 13px;
                            font-weight: 700;
                            text-color: Theme.text-secondary;
                            wrap: word-wrap;
                            capture(a, c) => { root.capture-selection(i, a, c); }
                        }
                        // Paragraph (+ A2 star gutter on the right)
                        if block.kind == 0 : HorizontalLayout {
                            spacing: 4px;
                            SelectableText {
                                text: block.display-text;
                                source-text: block.text;
                                font-size: Metrics.font-body;
                                text-color: Theme.text-secondary;
                                wrap: word-wrap;
                                horizontal-stretch: 1;
                                capture(a, c) => { root.capture-selection(i, a, c); }
                            }
                            StarMark {
                                marked: block.marked;
                                clicked(shift) => { root.toggle-block-marked(i, shift); }
                            }
                        }
                        // Bullet
                        if block.kind == 4 : HorizontalLayout {
                            padding-left: 12px;
                            spacing: Metrics.space-sm;
                            Text {
                                text: "•";
                                font-size: Metrics.font-body;
                                color: Theme.accent;
                                width: 10px;
                            }
                            SelectableText {
                                text: block.display-text;
                                source-text: block.text;
                                font-size: Metrics.font-body;
                                text-color: Theme.text-secondary;
                                wrap: word-wrap;
                                horizontal-stretch: 1;
                                capture(a, c) => { root.capture-selection(i, a, c); }
                            }
                            StarMark {
                                marked: block.marked;
                                clicked(shift) => { root.toggle-block-marked(i, shift); }
                            }
                        }
                        // User turn. Reuses a fenced `user` block from the
                        // conversation renderer, but looks like a chat bubble
                        // instead of source code.
                        if block.kind == 5 && block.lang == "user" : Rectangle {
                            height: user-layout.preferred-height;
                            vertical-stretch: 0;
                            background: Theme.accent.with-alpha(0.14);
                            border-radius: 7px;
                            border-width: 1px;
                            border-color: Theme.accent.with-alpha(0.55);
                            user-layout := VerticalLayout {
                                padding: Metrics.space-sm;
                                spacing: 4px;
                                Text {
                                    text: @tr("You");
                                    font-size: 10px;
                                    font-weight: 700;
                                    color: Theme.accent;
                                }
                                SelectableText {
                                    text: block.display-text;
                                    source-text: block.text;
                                    font-size: Metrics.font-body;
                                    text-color: Theme.text-primary;
                                    wrap: word-wrap;
                                    capture(a, c) => { root.capture-selection(i, a, c); }
                                }
                            }
                        }
                        // Code block
                        if block.kind == 5 && block.lang != "user" : Rectangle {
                            background: Theme.code-bg;
                            border-radius: 4px;
                            border-width: 1px;
                            border-color: Theme.border;
                            clip: true;
                            VerticalLayout {
                                padding: Metrics.space-sm;
                                spacing: Metrics.space-xs;
                                // Header: language label (left) + per-block copy
                                // button (right). The button copies THIS block's
                                // clean code — `block.text` is the fence-stripped
                                // body, so no backticks reach the clipboard.
                                HorizontalLayout {
                                    spacing: Metrics.space-sm;
                                    Text {
                                        text: block.lang;
                                        font-size: 9px;
                                        color: Theme.text-muted;
                                        vertical-alignment: center;
                                    }
                                    Rectangle { horizontal-stretch: 1; }
                                    Rectangle {
                                        width: 22px;
                                        height: 18px;
                                        border-radius: 4px;
                                        background: cb-touch.has-hover ? Theme.border-strong : transparent;
                                        cb-touch := TouchArea {
                                            clicked => { root.copy-block-clicked(i, block.text); }
                                        }
                                        Image {
                                            source: root.copied-block-index == i
                                                ? @image-url("../assets/icons/check.svg")
                                                : @image-url("../assets/icons/copy.svg");
                                            colorize: root.copied-block-index == i ? Theme.success : Theme.text-muted;
                                            width: 12px;
                                            height: 12px;
                                            image-fit: contain;
                                            x: (parent.width - self.width) / 2;
                                            y: (parent.height - self.height) / 2;
                                        }
                                    }
                                    StarMark {
                                        marked: block.marked;
                                        clicked(shift) => { root.toggle-block-marked(i, shift); }
                                    }
                                }
                                // Code keeps no-wrap so commands / YAML / JSON
                                // don't reflow and lose meaning; long lines
                                // clip at the box edge (clip:true) — maximize
                                // the tile (maximize button) to read them in full.
                                SelectableText {
                                    text: block.display-text;
                                    source-text: block.text;
                                    font-size: 11px;
                                    text-color: Theme.code-text;
                                    mono-family: Theme.font-mono;
                                    wrap: no-wrap;
                                    capture(a, c) => { root.capture-selection(i, a, c); }
                                }
                            }
                        }
                        // HR
                        if block.kind == 6 : Rectangle {
                            background: Theme.border;
                            height: 1px;
                        }
                        // Table (kind 7) — aligned monospace block (#109).
                        // no-wrap preserves column alignment; very wide
                        // tables clip on the right rather than scrambling
                        // (maximize the tile to see them in full).
                        if block.kind == 7 : Rectangle {
                            background: Theme.code-bg;
                            border-radius: 4px;
                            border-width: 1px;
                            border-color: Theme.border;
                            VerticalLayout {
                                padding: Metrics.space-sm;
                                SelectableText {
                                    text: block.display-text;
                                    source-text: block.text;
                                    font-size: 11px;
                                    text-color: Theme.code-text;
                                    mono-family: Theme.font-mono;
                                    wrap: no-wrap;
                                    capture(a, c) => { root.capture-selection(i, a, c); }
                                }
                            }
                        }
                    }
                }
            }

            // R1/RS2 — whole-answer selection uses the standard scrollable TextEdit.
            // Its cursor-position tracking auto-scrolls while the mouse is dragged
            // below the viewport; the old SelectableText inside an outer ScrollView
            // could only select the currently visible part. Hidden
            // while EDITING a captured selection (capture-pending) — the editor below then gets the
            // full space, so its «В память» save button can't be pushed off (the real RS2 bug: the
            // big field + the editor + the button stacked past the window). min-height:0 so it takes
            // only the leftover space here.
            if root.select-mode && !root.capture-pending : TextEdit {
                vertical-stretch: 1;
                horizontal-stretch: 1;
                min-height: 0px;
                text: root.select-text;
                read-only: true;
                wrap: word-wrap;
                font-size: Metrics.font-body;
                key-pressed(e) => {
                    if (e.modifiers.control && !e.modifiers.shift) {
                        if (e.text == "с" || e.text == "С") { self.copy(); return accept; }
                        if (e.text == "ф" || e.text == "Ф") { self.select-all(); return accept; }
                    }
                    return reject;
                }
            }

            // A2 (ТЗ 2026-07-02) — «⭐ В память» action bar: shows once ≥1 block is
            // marked. N==1 exposes the edit buffer (trim-before-save, the flow the
            // tester accepted on the transcript); N>1 saves each marked block as its
            // own fact (edit later in Настройки → Память).
            if root.marked-count >= 1 || root.capture-pending : VerticalLayout {
                spacing: Metrics.space-xs;
                // Editor: the single-mark trim buffer OR a pending selection. A BOUNDED, scrollable
                // multi-line TextEdit (was a LineEdit) — a big captured selection is editable + scrolls
                // WITHIN 160px instead of filling the area and pushing «В память»/«Отмена» off (RS2).
                if root.marked-count == 1 || root.capture-pending : TextEdit {
                    text <=> root.capture-text;
                    wrap: word-wrap;
                    min-height: 44px;
                    max-height: 160px;
                }
                HorizontalLayout {
                    spacing: Metrics.space-sm;
                    Rectangle { horizontal-stretch: 1; }
                    Button {
                        text: root.capture-pending ? @tr("To memory") : @tr("To memory ({})", root.marked-count);
                        clicked => {
                            if (root.capture-pending) { root.save-capture(); }
                            else { root.save-marked(); }
                        }
                    }
                    // P5 — copy the marked blocks (only when marking, not for a pending selection
                    // which the user can already Ctrl+C from the editor above).
                    if root.marked-count >= 1 : Button {
                        text: @tr("Copy");
                        clicked => { root.copy-marked(); }
                    }
                    Button {
                        text: @tr("Cancel");
                        clicked => {
                            if (root.capture-pending) { root.cancel-capture(); }
                            else { root.clear-marks(); }
                        }
                    }
                }
            }

            // The active read-aloud controls stay visible at the bottom instead of
            // disappearing into the overflow popup. Keeping changing playback state
            // out of PopupWindow also avoids tearing down popup rows while focus moves
            // to Settings or another tile.
            if root.speak-active : Rectangle {
                height: 60px;
                background: Theme.bg-elevated;
                border-color: Theme.border-strong;
                border-width: 1px;
                border-radius: 7px;
                VerticalLayout {
                    padding-top: 8px;
                    padding-bottom: 8px;
                    padding-left: 8px;
                    padding-right: 8px;
                    spacing: 3px;
                    Text {
                        text: root.speak-loading ? @tr("Preparing voice...") : @tr("Reading aloud");
                        color: root.speak-loading ? Theme.accent : Theme.text-muted;
                        font-size: 10px;
                        overflow: elide;
                        vertical-alignment: center;
                        height: 11px;
                    }
                    HorizontalLayout {
                        height: 30px;
                        transport := HorizontalLayout {
                            horizontal-stretch: 0;
                            spacing: 4px;
                            TilePlayerButton {
                                label: "-10";
                                quiet: true;
                                a11y: @tr("Back 10 seconds");
                                clicked => { root.speak-seek-clicked(-10); }
                            }
                            TilePlayerButton {
                                primary: true;
                                icon: root.speak-paused
                                    ? @image-url("../assets/icons/play.svg")
                                    : @image-url("../assets/icons/pause.svg");
                                a11y: @tr("Pause / resume reading aloud");
                                clicked => { root.speak-pause-clicked(); }
                            }
                            TilePlayerButton {
                                label: "+15";
                                quiet: true;
                                a11y: @tr("Forward 15 seconds");
                                clicked => { root.speak-seek-clicked(15); }
                            }
                        }
                        Rectangle { horizontal-stretch: 1; }
                        secondary := HorizontalLayout {
                            horizontal-stretch: 0;
                            spacing: 6px;
                            TilePlayerButton {
                                icon: @image-url("../assets/icons/stop.svg");
                                icon-color: Theme.danger;
                                a11y: @tr("Stop reading aloud");
                                clicked => { root.speak-clicked(); }
                            }
                            speed-button := Rectangle {
                                width: 46px;
                                height: 30px;
                                background: speed-touch.has-hover ? Theme.bg-surface : transparent;
                                border-radius: 15px;
                                border-width: 1px;
                                border-color: Theme.border-strong;
                                accessible-role: button;
                                accessible-label: @tr("Reading speed") + ": " + root.speak-speed-label;
                                Text {
                                    text: root.speak-speed-label;
                                    color: Theme.text-secondary;
                                    font-size: 10px;
                                    horizontal-alignment: center;
                                    vertical-alignment: center;
                                }
                                speed-touch := TouchArea {
                                    mouse-cursor: pointer;
                                    clicked => { root.speak-speed-next-clicked(); }
                                }
                            }
                        }
                    }
                }
            }

            // ===== Follow-up input — continue the dialog in this tile =====
            // Phase E6 v45 — only shown for tiles that carry a conversation
            // (F9 / push-to-record answers; convo-id >= 0). Enter or the
            // → button sends; both are disabled while the answer streams.
            // User: "нет возможности продолжить диалог в рамках тайла".
            if root.convo-id >= 0 : HorizontalLayout {
                spacing: Metrics.space-sm;
                LineEdit {
                    placeholder-text: @tr("Continue the dialog…");
                    text <=> root.followup-text;
                    enabled: !root.followup-busy;
                    horizontal-stretch: 1;
                    accepted => {
                        root.do-submit();
                    }
                }
                // V0.8.4 — voice follow-up with the SAME Telegram-style swipe-up-to-
                // lock gesture as the bar's record chips: hold 🎤 to record, release
                // to send; drag up past 24px → hands-free (releasing keeps recording;
                // click ⏹ to stop + send). Drives the existing toggle at press (start)
                // / stop; the release-stop is gated on voice-recording so a mic-busy
                // tap can't spuriously start a recording on release. Border colour
                // marks state: grey idle · amber holding · red locked.
                voicebtn := Rectangle {
                    property <bool> v-locked: false;
                    property <length> v-press-y;
                    property <bool> v-swallow: false;
                    property <bool> v-rec: root.voice-recording;
                    width: 36px;
                    border-radius: 6px;
                    border-width: 1px;
                    border-color: voicebtn.v-locked ? Theme.danger
                        : (root.voice-recording ? Theme.warning : Theme.border);
                    changed v-rec => {
                        if (!voicebtn.v-rec) {
                            voicebtn.v-locked = false;
                        }
                    }
                    // Idle = mic icon; recording states use SVG stop / arrow-up
                    // icons for font-independent rendering.
                    if !root.voice-recording && !voicebtn.v-locked : Image {
                        source: @image-url("../assets/icons/mic.svg");
                        colorize: Theme.text-secondary;
                        width: 15px;
                        height: 15px;
                        image-fit: contain;
                        x: (parent.width - self.width) / 2;
                        y: (parent.height - self.height) / 2;
                    }
                    if root.voice-recording || voicebtn.v-locked : Image {
                        source: voicebtn.v-locked
                            ? @image-url("../assets/icons/stop.svg")
                            : @image-url("../assets/icons/arrow-up.svg");
                        colorize: voicebtn.v-locked ? Theme.danger : Theme.warning;
                        width: 15px;
                        height: 15px;
                        image-fit: contain;
                        x: (parent.width - self.width) / 2;
                        y: (parent.height - self.height) / 2;
                    }
                    vtouch := TouchArea {
                        mouse-cursor: pointer;
                        enabled: !root.followup-busy || root.voice-recording;
                        pointer-event(ev) => {
                            if (ev.button == PointerEventButton.left) {
                                if (ev.kind == PointerEventKind.down) {
                                    if (voicebtn.v-locked) {
                                        // Fresh click while locked = stop + send.
                                        voicebtn.v-locked = false;
                                        voicebtn.v-swallow = true;
                                        root.followup-voice-toggled();
                                    } else {
                                        voicebtn.v-press-y = self.mouse-y;
                                        voicebtn.v-swallow = false;
                                        root.followup-voice-toggled();
                                    }
                                }
                                if (ev.kind == PointerEventKind.up) {
                                    if (voicebtn.v-swallow) {
                                        voicebtn.v-swallow = false;
                                    } else if (!voicebtn.v-locked && root.voice-recording) {
                                        root.followup-voice-toggled();
                                    }
                                    // locked && !swallow = the release after a lock →
                                    // keep recording hands-free (do nothing).
                                }
                            }
                        }
                        moved => {
                            if (self.pressed && root.voice-recording && !voicebtn.v-locked
                                && voicebtn.v-press-y - self.mouse-y > 24px) {
                                voicebtn.v-locked = true;
                            }
                        }
                    }
                }
                Button {
                    text: root.followup-busy ? "…" : "→";
                    enabled: !root.followup-busy;
                    clicked => {
                        root.do-submit();
                    }
                }
            }
        }
    }
}

struct SpeakerRow {
    id: int,
    label: string,
    color: color,
}

component Tick inherits Rectangle {
    in property <bool> checked;
    callback clicked();
    width: 16px;
    height: 16px;
    border-radius: 3px;
    border-width: 1px;
    border-color: root.checked ? Theme.accent : Theme.border;
    background: root.checked ? Theme.accent : transparent;
    animate background, border-color { duration: 100ms; }
    // F5 — SVG check (project standard) instead of a text "✓". Centered via the
    // same fill+center layout the archive RowIcon uses (a bare Image won't center).
    if root.checked : VerticalLayout {
        alignment: center;
        HorizontalLayout {
            alignment: center;
            Image {
                source: @image-url("../assets/icons/check.svg");
                colorize: Theme.on-accent;
                width: 11px;
                height: 11px;
                image-fit: contain;
            }
        }
    }
    TouchArea {
        clicked => {
            root.clicked();
        }
    }
}

component TranscriptWindow inherits Window {
    property <bool> widgets-light: Theme.is-light;
    init => { Palette.color-scheme = root.widgets-light ? ColorScheme.light : ColorScheme.dark; }
    changed widgets-light => { Palette.color-scheme = root.widgets-light ? ColorScheme.light : ColorScheme.dark; }

    title: @tr("Transcript");
    icon: @image-url("../assets/icon.svg");
    // Opaque (NOT transparent) — a transparent + WS_EX_LAYERED frameless window
    // alpha-clamps text invisible (archive.slint learned this the hard way).
    background: Theme.bg-surface;
    no-frame: true;
    always-on-top: true;
    preferred-width: 720px;
    preferred-height: 560px;
    min-width: 480px;
    min-height: 320px;

    // Rust-built: session heading (title/time), the rows, and the empty flag.
    in-out property <string> heading: "";
    in-out property <[TranscriptLine]> lines: [];
    in-out property <bool> empty: false;
    // Баг5-class: how many utterances the display cap hid (0 = none). The footer
    // below the list discloses it so a long transcript isn't SILENTLY truncated
    // ("Copy all" still exports every line — it reads the full utterance set).
    in-out property <int> overflow-count: 0;
    // ТЗ1 copy (decision #7): "Copy all / selected" honour the "with timecodes"
    // toggle; `copied` flashes a 1.5s confirmation on the buttons (set from Rust).
    // `all-selected` mirrors the per-line checkboxes (kept in sync by Rust).
    in-out property <bool> with-timecodes: false;
    in-out property <bool> copied: false;
    in-out property <bool> all-selected: false;
    // ТЗ2b player: `has-audio` gates the mini-player; the rest are polled from
    // Rust — progress 0..1, "mm:ss / mm:ss" time, the active line index, play state.
    in-out property <bool> has-audio: false;
    in-out property <bool> playing: false;
    in-out property <float> progress: 0;
    in-out property <string> time-text: "";
    in-out property <int> active-line: -1;
    // Player speed + volume-boost (owner req 2026-07-05) — speed via a ComboBox
    // (1×–3× step 0.25, `speed-index`), volume via a Slider (0–3×). Applied through
    // set-speed / set-volume; Rust resets both per session.
    in-out property <int> speed-index: 0;
    in-out property <float> volume: 1.0;
    // G2b (2026-07-03) — «⭐ В память», mirrors the tiles: the per-line ⭐ toggles the
    // line's `marked`; one bottom «В память (N)» bar joins the marked lines into ONE
    // record. `capture-text` = the edit buffer (shown at N==1, or for a pending
    // selection); `capture-pending` = a right-click text-selection capture (independent
    // of the ⭐ marks, same split as the tiles).
    in-out property <int> marked-count: 0;
    // R1.2 (retest v0.28.0): last plain-clicked line — the anchor a SHIFT+click range-marks up to.
    // Reset by the Rust wiring on each fresh open (window is reused across sessions).
    in-out property <int> mark-anchor: -1;
    in-out property <string> capture-text: "";
    in-out property <bool> capture-pending: false;
    // Which single line seeded `capture-text` (-1 = none). Re-seed the edit buffer ONLY
    // when the SOLE-marked line changes, so an in-progress edit survives marking/unmarking
    // OTHER lines (mirrors the tile's review-I-1 guard).
    in-out property <int> capture-line-index: -1;

    // ── D3 — «По голосам» (speaker diarization) ──
    // false = «По ролям» (Микрофон/Система, default); true = «По голосам» (per-speaker).
    in-out property <bool> by-voice: false;
    // A diarization result exists for this session (enables the toggle).
    in-out property <bool> has-diarization: false;
    // The session can be diarized (finished + has system audio + aligned timecodes).
    in-out property <bool> can-diarize: false;
    // A diarization job is running (disabled button + status).
    in-out property <bool> diarizing: false;
    // V-1 (fable review): session IS diarizable but the models aren't installed → show
    // an install prompt (otherwise the whole toolbar is hidden and the feature is
    // undiscoverable + uninstallable).
    in-out property <bool> needs-diar-models: false;
    // The diarization models are downloading (progress in diar-status).
    in-out property <bool> installing-diar-models: false;
    // Windows RC: optional Nemotron engine. Legacy remains the default.
    in-out property <bool> use-nemotron: false;
    in-out property <bool> nemotron-available: false;
    // I-1 (fable review): this session's recording predates the wall-clock-padding fix
    // (D0.5), so audio_ms→sample drifts and speaker timings may be approximate → banner.
    in-out property <bool> timeline-unreliable: false;
    // F (fable) — re-detect guard: `has-speaker-names` (Rust-set) arms the guard; a re-run
    // wipes custom names, so `confirm-rediar` shows a confirm card first (clones archive resummary).
    in-out property <bool> has-speaker-names: false;
    in-out property <bool> confirm-rediar: false;
    // Progress / error line under the diarize controls.
    in-out property <string> diar-status: "";
    // «Сколько собеседников (без вас)» — the PRIMARY control (auto is unreliable on VoIP
    // audio). Default 2 (the common one-interviewer case).
    in-out property <int> speaker-count: 2;
    // The rename list, shown in «По голосам»: display id · label · colour.
    in-out property <[SpeakerRow]> speakers: [];
    // I (2026-07-05, owner top priority) — in-transcript search. `search-query` drives Rust
    // match-flagging (`matched` per line); `search-count`/`search-pos` show «pos / count».
    in-out property <string> search-query: "";
    in-out property <int> search-count: 0;
    in-out property <int> search-pos: 0; // 1-based; 0 = no current match

    callback toggle-play();
    callback play-line(int);
    callback seek-fraction(float);
    // Player speed + volume-boost (owner req 2026-07-05) — the button cycles the value,
    // sets the property (drives its own label), and hands the new value to Rust.
    callback set-speed(float);
    callback set-volume(float);
    callback copy-all-requested();
    callback copy-selected-requested();
    callback toggle-line(int);
    callback toggle-all(bool);
    callback close-requested();
    callback drag-start-requested();
    callback drag-moved();
    // G2b (2026-07-03) — ⭐ multi-mark → save, mirroring the tiles: toggle a line's mark;
    // «В память (N)» joins ALL marked lines into ONE note; clear-marks cancels. R1.2: the bool is
    // whether SHIFT was held (range-mark from the anchor to this line); Rust owns the range logic.
    callback toggle-line-marked(int, bool);
    callback save-marked();
    callback clear-marks();
    // Right-click text-selection capture → the same editor (save / cancel).
    callback save-capture();
    callback cancel-capture();
    // ТЗ 2026-07-03 — mouse-selection capture: (line-index, anchor-byte-offset,
    // cursor-byte-offset). Rust slices line.text by the selection and opens the same
    // editor (capture-text + capture-pending) that the ⭐-mark flow uses.
    callback capture-line-selection(int, int, int);

    // D3 — «По голосам»: flip the view; run diarization with `speaker-count`; rename a
    // speaker (display id, new name — blank clears). Rust rebuilds `lines` + `speakers`.
    callback toggle-by-voice(bool);
    callback run-diarization();
    callback cancel-diarization();
    // V-1 — download the diarization models (shown only when the session is
    // diarizable but the models are absent).
    callback install-diar-models();
    callback select-diar-engine(bool);
    callback rename-speaker(int, string);
    // I — in-transcript search: `search-edited` re-flags matches on each keystroke; `search-jump(+1/-1)`
    // moves to the next/prev match (Rust jumps the player via play-line + calls scroll-to-line here).
    callback search-edited(string);
    callback search-jump(int);

    // I — scroll the virtualized ListView so line `idx` is roughly centered (same average-height
    // estimate std StandardListViewBase uses). Approximate with variable-height rows, but the audio
    // jump is exact + the 200ms poll then paints the landed row via active-line.
    public function scroll-to-line(idx: int) {
        if (root.lines.length == 0) {
            return;
        }
        lv.viewport-y = -clamp(
            idx * (lv.viewport-height / root.lines.length) - lv.height / 2,
            0px,
            max(0px, lv.viewport-height - lv.height));
    }

    forward-focus: fs;

    Rectangle {
        background: Theme.bg-surface.with-alpha(0.95);
        border-radius: Metrics.radius-panel;
        border-width: Metrics.border-thin;
        border-color: Theme.border;

        fs := FocusScope {
            width: 100%;
            height: 100%;
            key-pressed(event) => {
                if (event.text == Key.Escape) {
                    // F — Esc dismisses the re-detect confirm first, then closes the window.
                    if (root.confirm-rediar) {
                        root.confirm-rediar = false;
                    } else {
                        root.close-requested();
                    }
                    return accept;
                }
                return reject;
            }

            VerticalLayout {
                padding: Metrics.space-md;
                spacing: Metrics.space-sm;

                // ── Header: icon · title · session heading (DRAG) · close ──
                HorizontalLayout {
                    spacing: Metrics.space-sm;
                    Rectangle {
                        horizontal-stretch: 1;
                        TouchArea {
                            mouse-cursor: grab;
                            pointer-event(ev) => {
                                if (ev.button == PointerEventButton.left
                                    && ev.kind == PointerEventKind.down) {
                                    root.drag-start-requested();
                                }
                            }
                            moved => { if (self.pressed) { root.drag-moved(); } }
                        }
                        HorizontalLayout {
                            spacing: Metrics.space-sm;
                            Rectangle {
                                width: 18px;
                                height: 30px;
                                horizontal-stretch: 0;
                                Image {
                                    y: 6px;
                                    source: @image-url("../assets/icons/bubble.svg");
                                    colorize: Theme.text-primary;
                                    width: 18px;
                                    height: 18px;
                                    image-fit: contain;
                                }
                            }
                            Rectangle {
                                width: 13px;
                                height: 30px;
                                horizontal-stretch: 0;
                                DragGrip { y: 4px; }
                            }
                            Text {
                                text: @tr("Transcript");
                                font-size: Metrics.font-heading;
                                font-weight: 700;
                                color: Theme.text-primary;
                                vertical-alignment: center;
                            }
                            Text {
                                text: root.heading;
                                font-size: Metrics.font-caption;
                                color: Theme.text-muted;
                                vertical-alignment: center;
                                horizontal-stretch: 1;
                                overflow: elide;
                            }
                        }
                    }
                    CloseButton {
                        clicked => { root.close-requested(); }
                    }
                }

                Rectangle {
                    background: Theme.border;
                    height: Metrics.border-thin;
                }

                // ── Toolbar: copy all / copy selected + timecode toggle (ТЗ1 #7) ──
                if !root.empty : HorizontalLayout {
                    spacing: Metrics.space-sm;
                    Rectangle {
                        width: 124px;
                        height: 28px;
                        horizontal-stretch: 0;
                        border-radius: 6px;
                        background: copy-ta.pressed
                            ? Theme.accent.with-alpha(0.7)
                            : copy-ta.has-hover ? Theme.accent : Theme.accent.with-alpha(0.85);
                        animate background { duration: 120ms; }
                        copy-ta := TouchArea {
                            clicked => {
                                root.copy-all-requested();
                            }
                        }
                        Text {
                            // Per-scheme WCAG-AA text colour on the accent fill (white
                            // fails on the bright mint scheme); matches every other
                            // filled-accent control.
                            text: root.copied ? @tr("Copied [ok]") : @tr("Copy all");
                            color: Theme.on-accent;
                            font-size: Metrics.font-label;
                            font-weight: 600;
                            horizontal-alignment: center;
                            vertical-alignment: center;
                        }
                    }
                    Rectangle {
                        width: 150px;
                        height: 28px;
                        horizontal-stretch: 0;
                        border-radius: 6px;
                        border-width: 1px;
                        border-color: Theme.accent;
                        background: sel-ta.pressed
                            ? Theme.accent.with-alpha(0.22)
                            : sel-ta.has-hover ? Theme.accent.with-alpha(0.14) : transparent;
                        animate background { duration: 120ms; }
                        sel-ta := TouchArea {
                            clicked => {
                                root.copy-selected-requested();
                            }
                        }
                        Text {
                            text: root.copied ? @tr("Copied [ok]") : @tr("Copy selected");
                            color: Theme.accent;
                            font-size: Metrics.font-label;
                            font-weight: 600;
                            horizontal-alignment: center;
                            vertical-alignment: center;
                        }
                    }
                    DarkCheck {
                        text: @tr("with timecodes [mm:ss]");
                        checked <=> root.with-timecodes;
                    }
                }

                // ── D3 — «По голосам» diarization toolbar (view toggle + detect controls) ──
                // V-1: also show when the session is diarizable but models are absent, so
                // the install prompt is reachable (else the whole feature is hidden).
                if !root.empty && (root.can-diarize || root.has-diarization || root.needs-diar-models) : VerticalLayout {
                    spacing: Metrics.space-sm;
                    // G (fable) — the view-toggle row shows ONLY once a result exists. It used
                    // to sit inside an always-present HorizontalLayout wrapper, but an EMPTY box
                    // layout in Slint 1.16 reports stretch=f32::MAX (ate all vertical space → the
                    // ListView collapsed to ~2 rows) AND max-width=0 (opened the window narrower).
                    // Hoisting the `if` so NOTHING renders pre-detect fixes both. (D3 8b4fa2c regression.)
                    if root.has-diarization : HorizontalLayout {
                        spacing: 4px;
                        Rectangle {
                            width: 92px;
                            height: 28px;
                            border-radius: 6px;
                            border-width: 1px;
                            border-color: Theme.accent;
                            background: !root.by-voice ? Theme.accent : transparent;
                            role-ta := TouchArea { clicked => { root.toggle-by-voice(false); } }
                            Text {
                                text: @tr("By role");
                                color: !root.by-voice ? Theme.on-accent : Theme.accent;
                                font-size: Metrics.font-label;
                                font-weight: 600;
                                horizontal-alignment: center;
                                vertical-alignment: center;
                            }
                        }
                        Rectangle {
                            width: 104px;
                            height: 28px;
                            border-radius: 6px;
                            border-width: 1px;
                            border-color: Theme.accent;
                            background: root.by-voice ? Theme.accent : transparent;
                            voice-ta := TouchArea { clicked => { root.toggle-by-voice(true); } }
                            Text {
                                text: @tr("By voice");
                                color: root.by-voice ? Theme.on-accent : Theme.accent;
                                font-size: Metrics.font-label;
                                font-weight: 600;
                                horizontal-alignment: center;
                                vertical-alignment: center;
                            }
                        }
                        Rectangle { horizontal-stretch: 1; }
                    }
                    // I-1 (fable review) — system.wav is shorter than the SYSTEM-line span, so
                    // audio_ms→sample drifts and speaker labels may land off. E-fix: gate on
                    // has-diarization — the caveat is about label alignment, so it's meaningless
                    // (and was firing on every diarizable open) until a result actually exists.
                    if root.timeline-unreliable && root.has-diarization : Rectangle {
                        border-radius: 6px;
                        border-width: 1px;
                        border-color: Theme.warning;
                        background: Theme.warning.with-alpha(0.10);
                        HorizontalLayout {
                            padding: 6px;
                            Text {
                                text: @tr("Speaker timings may be approximate for this recording.");
                                font-size: Metrics.font-caption;
                                color: Theme.text-primary;
                                wrap: word-wrap;
                            }
                        }
                    }
                    // V-1 (fable review) — models missing: offer the one-time download. The
                    // detect controls (below) stay hidden until can-diarize flips true.
                    if root.needs-diar-models : VerticalLayout {
                        spacing: 4px;
                        Text {
                            text: root.use-nemotron ? @tr("Nemotron requires a one-time model download (~102 MB).") : @tr("Speaker detection needs a one-time model download (~30 MB).");
                            font-size: Metrics.font-caption;
                            color: Theme.text-muted;
                            wrap: word-wrap;
                        }
                        HorizontalLayout {
                            Rectangle {
                                width: 232px;
                                height: 28px;
                                horizontal-stretch: 0;
                                border-radius: 6px;
                                background: root.installing-diar-models
                                    ? Theme.accent.with-alpha(0.5)
                                    : instd-ta.has-hover ? Theme.accent : Theme.accent.with-alpha(0.85);
                                animate background { duration: 120ms; }
                                instd-ta := TouchArea {
                                    clicked => { if (!root.installing-diar-models) { root.install-diar-models(); } }
                                }
                                Text {
                                    text: root.installing-diar-models
                                        ? @tr("Downloading models…")
                                        : @tr("Install speaker models");
                                    color: Theme.on-accent;
                                    font-size: Metrics.font-label;
                                    font-weight: 600;
                                    horizontal-alignment: center;
                                    vertical-alignment: center;
                                }
                            }
                            Rectangle { horizontal-stretch: 1; }
                        }
                    }
                    // Optional Windows RC engine toggle. Do not change archived results
                    // or the legacy default just by switching the choice.
                    if root.can-diarize || root.needs-diar-models : HorizontalLayout {
                        spacing: Metrics.space-sm;
                        Text {
                            text: @tr("Speaker engine:");
                            font-size: Metrics.font-label;
                            color: Theme.text-muted;
                            vertical-alignment: center;
                        }
                        Rectangle {
                            width: 112px;
                            height: 28px;
                            border-radius: 6px;
                            border-width: 1px;
                            border-color: Theme.border;
                            background: !root.use-nemotron ? Theme.accent.with-alpha(0.20) : Theme.bg-surface;
                            TouchArea { clicked => { if (!root.diarizing && !root.installing-diar-models) { root.select-diar-engine(false); } } }
                            Text { text: @tr("Legacy"); color: Theme.text-primary; horizontal-alignment: center; vertical-alignment: center; }
                        }
                        if root.nemotron-available : Rectangle {
                            width: 112px;
                            height: 28px;
                            border-radius: 6px;
                            border-width: 1px;
                            border-color: Theme.border;
                            background: root.use-nemotron ? Theme.accent.with-alpha(0.20) : Theme.bg-surface;
                            TouchArea { clicked => { if (!root.diarizing && !root.installing-diar-models) { root.select-diar-engine(true); } } }
                            Text { text: @tr("Nemotron 3"); color: Theme.text-primary; horizontal-alignment: center; vertical-alignment: center; }
                        }
                        Rectangle { horizontal-stretch: 1; }
                    }
                    // ── Row 2 — detect controls (count stepper + run button; own row so
                    // the fixed-width controls never overflow the min-width window). Gated on
                    // can-diarize (V-1) — hidden until the models are installed. ──
                    if root.can-diarize : HorizontalLayout {
                        spacing: Metrics.space-sm;
                        // Speaker-count stepper — the PRIMARY control («сколько собеседников»).
                        // V-2: the count is OTHER voices (diarization runs on system.wav; your
                        // mic is a separate channel), so «besides you».
                        if !root.use-nemotron : Text {
                            text: @tr("Speakers (besides you):");
                            font-size: Metrics.font-label;
                            color: Theme.text-muted;
                            vertical-alignment: center;
                        }
                        if !root.use-nemotron : Rectangle {
                            width: 26px;
                            height: 28px;
                            border-radius: 6px;
                            border-width: 1px;
                            border-color: Theme.border;
                            TouchArea { clicked => { if (root.speaker-count > 0) { root.speaker-count -= 1; } } }
                            Text {
                                text: "−";
                                font-size: Metrics.font-body;
                                color: Theme.text-primary;
                                horizontal-alignment: center;
                                vertical-alignment: center;
                            }
                        }
                        if !root.use-nemotron : Text {
                            text: root.speaker-count == 0 ? @tr("Auto") : "\{root.speaker-count}";
                            width: 22px;
                            font-size: Metrics.font-body;
                            font-weight: 700;
                            color: Theme.text-primary;
                            horizontal-alignment: center;
                            vertical-alignment: center;
                        }
                        if !root.use-nemotron : Rectangle {
                            width: 26px;
                            height: 28px;
                            border-radius: 6px;
                            border-width: 1px;
                            border-color: Theme.border;
                            TouchArea { clicked => { if (root.speaker-count < 8) { root.speaker-count += 1; } } }
                            Text {
                                text: "+";
                                font-size: Metrics.font-body;
                                color: Theme.text-primary;
                                horizontal-alignment: center;
                                vertical-alignment: center;
                            }
                        }
                        if root.use-nemotron : Text {
                            text: @tr("Speakers: automatic (up to 8)");
                            font-size: Metrics.font-label;
                            color: Theme.text-muted;
                            vertical-alignment: center;
                        }
                        Rectangle { horizontal-stretch: 1; }
                        if root.use-nemotron && root.diarizing : Rectangle {
                            width: 84px;
                            height: 28px;
                            border-radius: 6px;
                            border-width: 1px;
                            border-color: Theme.border;
                            TouchArea { clicked => { root.cancel-diarization(); } }
                            Text {
                                text: @tr("Cancel");
                                font-size: Metrics.font-label;
                                color: Theme.text-primary;
                                horizontal-alignment: center;
                                vertical-alignment: center;
                            }
                        }
                        Rectangle {
                            width: 176px;
                            height: 28px;
                            border-radius: 6px;
                            background: root.diarizing
                                ? Theme.accent.with-alpha(0.5)
                                : dia-ta.has-hover ? Theme.accent : Theme.accent.with-alpha(0.85);
                            animate background { duration: 120ms; }
                            dia-ta := TouchArea {
                                clicked => {
                                    if (!root.diarizing) {
                                        // F — confirm before a re-run that would wipe custom names.
                                        if (root.has-diarization && root.has-speaker-names) {
                                            root.confirm-rediar = true;
                                        } else {
                                            root.run-diarization();
                                        }
                                    }
                                }
                            }
                            Text {
                                text: root.has-diarization ? @tr("Re-detect speakers") : @tr("Detect speakers");
                                color: Theme.on-accent;
                                font-size: Metrics.font-label;
                                font-weight: 600;
                                horizontal-alignment: center;
                                vertical-alignment: center;
                            }
                        }
                    }
                    // Progress / error line.
                    if root.diar-status != "" : Text {
                        text: root.diar-status;
                        font-size: Metrics.font-caption;
                        color: Theme.text-muted;
                        wrap: word-wrap;
                    }
                    // Rename list (voice view): coloured dot + editable name per speaker.
                    // V-3 (fable review): a horizontal ScrollView bounds the row so 5+ speakers
                    // scroll instead of overflowing the window (the «Память >4» bug shape). For
                    // the common 2–3 speakers it fits and no scrollbar shows.
                    if root.by-voice && root.speakers.length > 0 : ScrollView {
                        height: 42px;
                        HorizontalLayout {
                            spacing: Metrics.space-md;
                            for sp[si] in root.speakers : HorizontalLayout {
                                spacing: 5px;
                                Rectangle {
                                    width: 11px;
                                    height: 11px;
                                    border-radius: 5px;
                                    background: sp.color;
                                    y: (parent.height - self.height) / 2;
                                }
                                LineEdit {
                                    text: sp.label;
                                    width: 108px;
                                    font-size: Metrics.font-label;
                                    // A re-detect replaces the whole diarization row. Prevent a
                                    // late rename write from restoring the previous segments.
                                    enabled: !root.diarizing;
                                    // F-fix (fable, live-proven): commit AS-TYPED, not just on Enter.
                                    // The old Enter-only `accepted` let a typed-but-uncommitted name sit
                                    // VISIBLE while the store stayed empty → the re-detect guard saw no
                                    // names and silently re-ran («не спрашивает»). `edited` keeps the store
                                    // equal to the visible text; a blank value clears the rename.
                                    edited(t) => { root.rename-speaker(sp.id, t); }
                                }
                            }
                        }
                    }
                }

                // ── I (2026-07-05, owner top priority) — in-transcript search row: type → matching
                // lines tint; Enter / ‹ › jump the player to a match's moment + scroll the list to it. ──
                if !root.empty : HorizontalLayout {
                    spacing: Metrics.space-sm;
                    padding-left: 4px;
                    LineEdit {
                        horizontal-stretch: 1;
                        text <=> root.search-query;
                        placeholder-text: @tr("Search in transcript");
                        font-size: Metrics.font-label;
                        edited(t) => { root.search-edited(t); }
                        accepted => { root.search-jump(1); }
                    }
                    if root.search-query != "" : Text {
                        text: "\{root.search-pos} / \{root.search-count}";
                        font-size: Metrics.font-caption;
                        color: Theme.text-muted;
                        vertical-alignment: center;
                    }
                    // ‹ prev / › next match (ASCII, per the v0.25.1 lesson: skia draws exotic glyphs square).
                    Rectangle {
                        width: 26px;
                        height: 28px;
                        border-radius: 6px;
                        border-width: 1px;
                        border-color: Theme.border;
                        TouchArea { clicked => { root.search-jump(-1); } }
                        Text {
                            text: "<";
                            font-size: Metrics.font-body;
                            color: Theme.text-primary;
                            horizontal-alignment: center;
                            vertical-alignment: center;
                        }
                    }
                    Rectangle {
                        width: 26px;
                        height: 28px;
                        border-radius: 6px;
                        border-width: 1px;
                        border-color: Theme.border;
                        TouchArea { clicked => { root.search-jump(1); } }
                        Text {
                            text: ">";
                            font-size: Metrics.font-body;
                            color: Theme.text-primary;
                            horizontal-alignment: center;
                            vertical-alignment: center;
                        }
                    }
                }

                // ── "Select all" header above the list ──
                if !root.empty : HorizontalLayout {
                    spacing: Metrics.space-sm;
                    padding-left: 4px;
                    Tick {
                        checked: root.all-selected;
                        clicked => {
                            root.toggle-all(!root.all-selected);
                        }
                    }
                    Text {
                        text: @tr("select all");
                        font-size: Metrics.font-caption;
                        color: Theme.text-muted;
                        vertical-alignment: center;
                        horizontal-stretch: 1;
                    }
                }

                // ── Empty: no saved transcript ──
                if root.empty : Text {
                    text: @tr("Transcript not saved");
                    font-size: Metrics.font-label;
                    color: Theme.text-muted;
                    horizontal-alignment: center;
                    vertical-alignment: center;
                    vertical-stretch: 1;
                    wrap: word-wrap;
                }

                // ── Chronological transcript rows ──
                // I-fix — UNCONDITIONAL so the `lv` name is reachable from scroll-to-line (Slint
                // can't reference a conditional element from a function). Empty → stretch 0 so the
                // "Transcript not saved" placeholder (above) fills instead; 0 rows render anyway.
                lv := ListView {
                    // Virtualized (only VISIBLE rows are instantiated) → the list height is no
                    // longer bounded by the SW-renderer i16 (32767px) limit, so ALL utterances
                    // show — no display cap. Per-row `max-height:120px` + clip still bounds any
                    // single very long utterance.
                    vertical-stretch: root.empty ? 0 : 1;
                    for line[i] in root.lines : Rectangle {
                            // Баг5 — clamp + clip so ONE long utterance can't grow the
                            // row unbounded; with TRANSCRIPT_DISPLAY_CAP this keeps the
                            // un-virtualized list under the SW renderer's i16 (32767px)
                            // coordinate limit (see the guard in aux_windows.rs). The
                            // clipped tail is still in "Copy all".
                            max-height: 120px;
                            clip: true;
                            // Active-line highlight (ТЗ2b) — the row whose timecode
                            // contains the current playback position.
                            background: i == root.active-line
                                ? Theme.accent.with-alpha(0.14)
                                : line.matched ? Theme.warning.with-alpha(0.12)
                                : transparent;
                            border-radius: 4px;
                            // Clicking the row (anywhere but the checkbox) plays the
                            // mix from this line's moment (ТЗ2b). The Tick's own
                            // TouchArea below intercepts checkbox clicks first.
                            TouchArea {
                                clicked => {
                                    root.play-line(i);
                                }
                            }
                            HorizontalLayout {
                                spacing: Metrics.space-sm;
                                padding-left: 4px;
                                // Keep the star column left of the ListView scrollbar using the
                                // standard visual-audit gutter, so it stays clickable and visible.
                                padding-right: 14px;
                                padding-top: 1px;
                                padding-bottom: 1px;
                                Tick {
                                    checked: line.checked;
                                    clicked => {
                                        root.toggle-line(i);
                                    }
                                }
                                // Omit the time column entirely when the session
                                // start is unknown (matches the markdown view).
                                if line.offset-label != "" : Text {
                                    text: line.offset-label;
                                    font-size: Metrics.font-caption;
                                    color: Theme.text-muted;
                                    vertical-alignment: top;
                                    width: 52px;
                                }
                                Text {
                                    text: line.speaker;
                                    font-size: Metrics.font-caption;
                                    font-weight: 700;
                                    // Role view: the theme accent (scheme-aware). Voice view:
                                    // the per-speaker palette colour Rust set on the line.
                                    color: root.by-voice ? line.speaker-color : Theme.accent;
                                    vertical-alignment: top;
                                    width: root.by-voice ? 120px : 84px;
                                    wrap: word-wrap;
                                }
                                // ТЗ 2026-07-03 — selectable (read-only TextInput):
                                // drag-select → right-click Copy / ⭐-to-memory. Clicks
                                // on the text now go to selection, so the row's play-line
                                // seek stays on the timecode/speaker columns + padding
                                // (plain Texts, clicks fall through to the row TouchArea).
                                SelectableText {
                                    text: line.display-text;
                                    source-text: line.text;
                                    font-size: Metrics.font-body;
                                    text-color: Theme.text-secondary;
                                    horizontal-stretch: 1;
                                    wrap: word-wrap;
                                    capture(a, c) => { root.capture-line-selection(i, a, c); }
                                }
                                // G2b — ⭐ MULTI-mark this line (toggle), like the tiles.
                                // Its own TouchArea intercepts the click so it doesn't also
                                // trigger the row's play-line (like the Tick above). Mark
                                // several → one «В память (N)» bar below.
                                Rectangle {
                                    width: 22px;
                                    height: 16px;
                                    border-radius: 4px;
                                    background: star-ta.has-hover ? Theme.border-strong : transparent;
                                    star-ta := TouchArea {
                                        // R1.2: latch SHIFT on pointer-down, fire on `clicked` (keeps
                                        // click-cancel-on-drag-off — same pattern as the tiles' StarMark).
                                        property <bool> shift-latched;
                                        pointer-event(e) => {
                                            if (e.kind == PointerEventKind.down) {
                                                self.shift-latched = e.modifiers.shift;
                                            }
                                        }
                                        clicked => {
                                            root.toggle-line-marked(i, self.shift-latched);
                                        }
                                    }
                                    // Muted outline star (SVG), same as the tiles' StarMark:
                                    // accent + full opacity when marked; muted + dim at rest.
                                    Image {
                                        source: @image-url("../assets/icons/star.svg");
                                        colorize: line.marked ? Theme.accent : (star-ta.has-hover ? Theme.accent : Theme.text-muted);
                                        opacity: line.marked ? 1.0 : (star-ta.has-hover ? 1.0 : 0.5);
                                        width: 13px;
                                        height: 13px;
                                        image-fit: contain;
                                        x: (parent.width - self.width) / 2;
                                        y: (parent.height - self.height) / 2;
                                    }
                                }
                            }
                        }
                }

                // G2b — «В память» bar (mirrors the tiles): shows when ≥1 line is
                // ⭐-marked OR a text selection is pending. N==1 / a selection exposes the
                // edit buffer to trim before save; N>1 joins the marked lines into ONE
                // record. «В память (N)» = save-marked; a pending selection = save-capture.
                if root.marked-count >= 1 || root.capture-pending : VerticalLayout {
                    spacing: Metrics.space-sm;
                    // RS2: bounded, scrollable multi-line editor (was a LineEdit) so a big captured
                    // selection scrolls within 160px instead of pushing «В память»/«Отмена» off.
                    if root.marked-count == 1 || root.capture-pending : TextEdit {
                        text <=> root.capture-text;
                        wrap: word-wrap;
                        min-height: 44px;
                        max-height: 160px;
                    }
                    HorizontalLayout {
                        spacing: Metrics.space-sm;
                        Rectangle { horizontal-stretch: 1; }
                        Button {
                            text: root.capture-pending ? @tr("To memory") : @tr("To memory ({})", root.marked-count);
                            clicked => {
                                if (root.capture-pending) {
                                    root.save-capture();
                                } else {
                                    root.save-marked();
                                }
                            }
                        }
                        Button {
                            text: @tr("Cancel");
                            clicked => {
                                if (root.capture-pending) {
                                    root.cancel-capture();
                                } else {
                                    root.clear-marks();
                                }
                            }
                        }
                    }
                }

                // ── Overflow footer (Баг5): the list is capped under the SW-renderer
                // i16 limit; disclose the hidden tail so a long transcript isn't
                // silently cut. "Copy all" still exports every line (full utterances).
                if root.overflow-count > 0 : Text {
                    text: @tr("{} more lines not shown - use 'Copy all' for the full transcript", root.overflow-count);
                    font-size: Metrics.font-caption;
                    color: Theme.text-muted;
                    horizontal-alignment: center;
                    wrap: word-wrap;
                }

                // ── Mini-player (ТЗ2b): play/pause · seek-bar · time ──
                if root.has-audio : HorizontalLayout {
                    spacing: Metrics.space-sm;
                    Rectangle {
                        width: 40px;
                        height: 28px;
                        horizontal-stretch: 0;
                        border-radius: 6px;
                        background: pp-ta.has-hover ? Theme.accent : Theme.accent.with-alpha(0.85);
                        animate background { duration: 120ms; }
                        pp-ta := TouchArea {
                            clicked => {
                                root.toggle-play();
                            }
                        }
                        // F5 — SVG play/pause (the main bar's icons) instead of the
                        // ▶/⏸ emoji; centered via fill+center layout.
                        VerticalLayout {
                            alignment: center;
                            HorizontalLayout {
                                alignment: center;
                                Image {
                                    source: root.playing
                                        ? @image-url("../assets/icons/pause.svg")
                                        : @image-url("../assets/icons/play.svg");
                                    colorize: Theme.on-accent;
                                    width: 14px;
                                    height: 14px;
                                    image-fit: contain;
                                }
                            }
                        }
                    }
                    // Seek-bar: click anywhere to jump to that fraction.
                    Rectangle {
                        horizontal-stretch: 1;
                        height: 28px;
                        seek-ta := TouchArea {
                            clicked => {
                                root.seek-fraction(self.mouse-x / self.width);
                            }
                        }
                        Rectangle {
                            y: (parent.height - self.height) / 2;
                            height: 6px;
                            border-radius: 3px;
                            background: Theme.border;
                            Rectangle {
                                x: 0;
                                width: parent.width * root.progress;
                                height: 100%;
                                border-radius: 3px;
                                background: Theme.accent;
                            }
                        }
                    }
                    Text {
                        text: root.time-text;
                        font-size: Metrics.font-caption;
                        color: Theme.text-muted;
                        vertical-alignment: center;
                    }
                    // Speed: ComboBox 1×–3× step 0.25 (owner req 2026-07-05). Pitch-
                    // preserving — set-speed routes through the time-stretch adapter.
                    ComboBox {
                        // Fixed width (not stretch) so the seek-bar keeps the lion's share
                        // of the row (owner: seek ≈ 4/6, speed ≈ 1/6, volume ≈ 1/6).
                        width: 80px;
                        horizontal-stretch: 0;
                        model: ["1×", "1.25×", "1.5×", "1.75×", "2×", "2.25×", "2.5×", "2.75×", "3×"];
                        current-index <=> root.speed-index;
                        selected(_) => {
                            root.set-speed(1.0 + root.speed-index * 0.25);
                        }
                    }
                    // Volume: Slider 0–3× (owner req «повышение звука») — boosts quiet
                    // recordings; applies live to the sink (no source rebuild). >1 may clip.
                    VerticalLayout {
                        alignment: center;
                        Image {
                            source: @image-url("../assets/icons/voice.svg");
                            colorize: Theme.accent;
                            width: 13px;
                            height: 13px;
                            image-fit: contain;
                        }
                    }
                    Slider {
                        // Fixed width (not stretch) — see the ComboBox note above.
                        width: 90px;
                        horizontal-stretch: 0;
                        minimum: 0;
                        maximum: 3.0;
                        value <=> root.volume;
                        changed(v) => {
                            root.set-volume(v);
                        }
                    }
                }
                if root.empty == false && root.has-audio == false : Text {
                    text: @tr("Audio not saved");
                    font-size: Metrics.font-caption;
                    color: Theme.text-muted;
                    horizontal-alignment: center;
                }
            }
        }

        // F (fable) — «Re-detect speakers?» confirm, an overlay sibling of `fs` (clones the
        // archive resummary scrim). Shown only when a result with custom names exists — a re-run
        // wipes the names (cluster ids permute), so guard it. Scrim-click / Cancel / Esc dismiss.
        if root.confirm-rediar : Rectangle {
            width: 100%;
            height: 100%;
            background: Theme.scrim;
