                x: (parent.width - self.width) / 2;
                y: (parent.height - self.height) / 2;
            }
        }
        Text {
            text: root.label;
            font-size: 12px;
            color: root.state == 1 ? Theme.accent : (root.state == 2 ? Theme.text-secondary : Theme.text-muted);
